UPDATE public.herbs SET active_compounds = ARRAY['The sesquiterpene dialdehyde polygodial has been identified as a fungitoxic active constituent [PMID:11562711].', 'terpenoids']::text[] WHERE slug = 'polygonum-punctatum' AND (active_compounds IS NULL OR cardinality(active_compounds) = 0);
UPDATE public.herbs SET active_compounds = ARRAY['The main iridoid for H.', 'iridoids']::text[] WHERE slug = 'harpagophytum-zeyheri' AND (active_compounds IS NULL OR cardinality(active_compounds) = 0);
UPDATE public.herbs SET active_compounds = ARRAY['The plant contains compounds capable of scavenging DPPH radicals [PMID:40063647, PMID:28974818].']::text[] WHERE slug = 'solanum-lasiocarpum' AND (active_compounds IS NULL OR cardinality(active_compounds) = 0);
UPDATE public.herbs SET active_compounds = ARRAY['essential oils']::text[] WHERE slug = 'barosma-betulina' AND (active_compounds IS NULL OR cardinality(active_compounds) = 0);
UPDATE public.herbs SET active_compounds = ARRAY['Protoanemonin is identified as the most relevant constituent of Pulsatilla pratensis L.']::text[] WHERE slug = 'pulsatilla-pratensis' AND (active_compounds IS NULL OR cardinality(active_compounds) = 0);
UPDATE public.herbs SET active_compounds = ARRAY['Paeonia obovata contains the monoterpene glycoside 6''-O-acetylpaeoniflorin, which is not detected in Paeonia lactiflora [PMID:25299493].', 'terpenoids', 'glycosides']::text[] WHERE slug = 'paeonia-obovata' AND (active_compounds IS NULL OR cardinality(active_compounds) = 0);
UPDATE public.herbs SET active_compounds = ARRAY['A key active compound identified in Paris chinensis is dioscin [PMID:22110264, PMID:21875297].']::text[] WHERE slug = 'paris-chinensis' AND (active_compounds IS NULL OR cardinality(active_compounds) = 0);
UPDATE public.herbs SET active_compounds = ARRAY['Flemiphilippinin A (Flp-A) is a bioactive compound isolated from Flemingia prostrata [PMID:40716126].']::text[] WHERE slug = 'flemingia-prostrata' AND (active_compounds IS NULL OR cardinality(active_compounds) = 0);
UPDATE public.herbs SET active_compounds = ARRAY['The species contains low molecular weight (LMW) glutenin genes [PMID:12724543].']::text[] WHERE slug = 'triticum-turgidum-subsp-durum' AND (active_compounds IS NULL OR cardinality(active_compounds) = 0);
UPDATE public.herbs SET active_compounds = ARRAY['Water-soluble polyphenolic-polysaccharide macromolecular glycoconjugates (14-50 kDa) isolated from the leaves [PMID:26848834, PMID:31765747].', 'polysaccharides']::text[] WHERE slug = 'rubus-plicatus' AND (active_compounds IS NULL OR cardinality(active_compounds) = 0);
UPDATE public.herbs SET active_compounds = ARRAY['Spelt genotypes exhibit protein content ranging from 12.1% to 22.2% [PMID:35885303].']::text[] WHERE slug = 'triticum-aestivum-subsp-spelta' AND (active_compounds IS NULL OR cardinality(active_compounds) = 0);
UPDATE public.herbs SET active_compounds = ARRAY['Sparteine is found in Spartium scoparium, specifically noted in specimens from Umbria [PMID:18894865].']::text[] WHERE slug = 'spartium-scoparium' AND (active_compounds IS NULL OR cardinality(active_compounds) = 0);
UPDATE public.herbs SET active_compounds = ARRAY['The plant contains an active principle shared with Rhus toxicodendron [PMID:19866830].']::text[] WHERE slug = 'rhus-venenata' AND (active_compounds IS NULL OR cardinality(active_compounds) = 0);
UPDATE public.herbs SET contraindications = ARRAY['Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are pregnant or breastfeeding.']::text[] WHERE slug = 'sophora-japonica-quercetin-phosphatidylcholine-complex' AND (contraindications IS NULL OR cardinality(contraindications) = 0);
UPDATE public.herbs SET contraindications = ARRAY['Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are pregnant or breastfeeding.', 'Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms persist or worsen.']::text[] WHERE slug = 'haematococcus-pluvialis-extract' AND (contraindications IS NULL OR cardinality(contraindications) = 0);
UPDATE public.herbs SET dosage_adult = '2 scoop / 3x daily' WHERE slug = 'actaea-dahurica';
UPDATE public.herbs SET dosage_adult = NULL WHERE slug = 'abies-balsamea';
UPDATE public.herbs SET dosage_adult = '5 mL / 1x Day(s); 5 mL' WHERE slug = 'abies-balsamea' AND COALESCE(dosage_adult, '') = '';
UPDATE public.herbs SET dosage_adult = '3 capsule / 3x daily' WHERE slug = 'menispermum-dauricum';
UPDATE public.herbs SET dosage_adult = '30 Pill / 2x daily' WHERE slug = 'glehnia-littoralis';
UPDATE public.herbs SET dosage_adult = '5 Granules' WHERE slug = 'acorus-gramineus';

-- ── 5. Mine regulator-backed drug_interactions from official monographs ──
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT 'd086ca76-314f-4f83-8011-a33d988e180b'::uuid, 'Corticosteroids (Prednisone)', '8640', 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking heart medications, corticosteroids, diuretics, or other health products that may contribute to electrolyte imbalance (EMA 2016; Gardner and McGuffin 2013; Brinker 2010). Consult a physician or pharmacist before combining with systemic corticosteroids.', 'Concomitant use with corticosteroids may increase the risk of potassium depletion or electrolyte imbalance, or alter immunological effects.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=aloe.oral.orale2&lang=eng', '{"fr": {"drug_name": "Corticostéroïdes (Prednisone)", "description": "Consultez un médecin ou un pharmacien avant toute association avec des corticostéroïdes systémiques. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking heart medications, corticosteroids, diuretics, or other health products that may contribute to electrolyte imbalance (EMA 2016; Gardner and McGuffin 2013; Brinker 2010). »)", "mechanism": "L''utilisation concomitante avec des corticostéroïdes peut accroître le risque d''hypokaliémie, de déséquilibre électrolytique ou d''interaction immunologique."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = 'd086ca76-314f-4f83-8011-a33d988e180b'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = 'd086ca76-314f-4f83-8011-a33d988e180b'::uuid AND lower(e.drug_name) = lower('Corticosteroids (Prednisone)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT 'e0c9d440-2056-4953-9450-6bf4220a7ac8'::uuid, 'Anticoagulants and Antiplatelets (Warfarin, Aspirin)', NULL, 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners or digoxin (Brinker 2010; Dasgupta et al. 2007; Elmer et al. 2007; Yuan et al. 2004). Consult a healthcare professional and monitor coagulation parameters (such as INR or bleeding signs) when combining with anticoagulant or antiplatelet therapy.', 'Potential additive antiplatelet or anticoagulant activity, or altered anticoagulant metabolism noted in official regulatory safety guidance.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=ginseng.american2&lang=eng', '{"fr": {"drug_name": "Anticoagulants et antiplaquettaires (Warfarine, Aspirine)", "description": "Consultez un professionnel de la santé et surveillez les paramètres de coagulation (RIN ou signes de saignement) lors de l''association avec un traitement anticoagulant ou antiplaquettaire. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners or digoxin (Brinker 2010; Dasgupta et al. 2007; Elmer et al. 2007; Yuan et al. 2004). »)", "mechanism": "Effet antiplaquettaire ou anticoagulant additif potentiel, ou altération du métabolisme des anticoagulants signalés dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = 'e0c9d440-2056-4953-9450-6bf4220a7ac8'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = 'e0c9d440-2056-4953-9450-6bf4220a7ac8'::uuid AND lower(e.drug_name) = lower('Anticoagulants and Antiplatelets (Warfarin, Aspirin)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT 'e0c9d440-2056-4953-9450-6bf4220a7ac8'::uuid, 'Digoxin', '3407', 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners or digoxin (Brinker 2010; Dasgupta et al. 2007; Elmer et al. 2007; Yuan et al. 2004). Do not combine with digoxin or other cardiac glycosides without direct medical supervision.', 'Potential cardiac glycoside sensitivity shift (including via potassium depletion or P-glycoprotein/inotropic effects) noted in regulatory safety warnings.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=ginseng.american2&lang=eng', '{"fr": {"drug_name": "Digoxine", "description": "Ne pas associer à la digoxine ou à d''autres glycosides cardiaques sans surveillance médicale directe. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners or digoxin (Brinker 2010; Dasgupta et al. 2007; Elmer et al. 2007; Yuan et al. 2004). »)", "mechanism": "Modification potentielle de la sensibilité aux glycosides cardiaques (notamment par déplétion potassique ou effet inotrope/P-gp) signalée dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = 'e0c9d440-2056-4953-9450-6bf4220a7ac8'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = 'e0c9d440-2056-4953-9450-6bf4220a7ac8'::uuid AND lower(e.drug_name) = lower('Digoxin'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '530677da-a71b-4cf7-a12b-166ab12960ea'::uuid, 'Levothyroxine (Synthroid)', '10582', 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking thyroid medications or antacids (Brinker 2010; Barnes et al. 2007B; Mills 1985). Consult a physician before use with thyroid medications and monitor thyroid function tests if combined.', 'Potential interference with thyroid hormone replacement or thyroid function noted in regulatory safety guidance.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=horseradish.raifort2&lang=eng', '{"fr": {"drug_name": "Lévothyroxine (Synthroid)", "description": "Consultez un médecin avant toute association avec des médicaments thyroïdiens et surveillez le bilan thyroïdien. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking thyroid medications or antacids (Brinker 2010; Barnes et al. 2007B; Mills 1985). »)", "mechanism": "Interférence potentielle avec le traitement substitutif par hormone thyroïdienne ou la fonction thyroïdienne signalée dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '530677da-a71b-4cf7-a12b-166ab12960ea'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '530677da-a71b-4cf7-a12b-166ab12960ea'::uuid AND lower(e.drug_name) = lower('Levothyroxine (Synthroid)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '36491807-8bdd-47de-ad34-53ef8c1526f5'::uuid, 'Anticoagulants and Antiplatelets (Warfarin, Aspirin)', NULL, 'moderate'::interaction_severity, 'Despite widespread use, bilberry has not been specifically linked to liver injury, either in the form of transient serum enzyme elevations or clinically apparent acute liver injury. Bilberry demonstrates minimal effect on drug metabolism but may affect platelet aggregation and predispose to excessive bleeding in patients on anticoagulants such as warfarin. Consult a healthcare professional and monitor coagulation parameters (such as INR or bleeding signs) when combining with anticoagulant or antiplatelet therapy.', 'Potential additive antiplatelet or anticoagulant activity, or altered anticoagulant metabolism noted in official regulatory safety guidance.', 'B', 'LiverTox', 'https://www.ncbi.nlm.nih.gov/books/n/livertox/Bilberry/', '{"fr": {"drug_name": "Anticoagulants et antiplaquettaires (Warfarine, Aspirine)", "description": "Consultez un professionnel de la santé et surveillez les paramètres de coagulation (RIN ou signes de saignement) lors de l''association avec un traitement anticoagulant ou antiplaquettaire. (Source officielle : LiverTox — « Despite widespread use, bilberry has not been specifically linked to liver injury, either in the form of transient serum enzyme elevations or clinically apparent acute liver injury. Bilberry demonstrates minimal effect on drug metabolism but may affect platelet aggregation and predispose to excessive bleeding in patients on anticoagulants such as warfarin. »)", "mechanism": "Effet antiplaquettaire ou anticoagulant additif potentiel, ou altération du métabolisme des anticoagulants signalés dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '36491807-8bdd-47de-ad34-53ef8c1526f5'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '36491807-8bdd-47de-ad34-53ef8c1526f5'::uuid AND lower(e.drug_name) = lower('Anticoagulants and Antiplatelets (Warfarin, Aspirin)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '7fc16acb-06c8-4431-84f7-112f68455e67'::uuid, 'Anticoagulants and Antiplatelets (Warfarin, Aspirin)', NULL, 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners or protease inhibitors (Brinker 2010; Mills and Bone 2005). Consult a healthcare professional and monitor coagulation parameters (such as INR or bleeding signs) when combining with anticoagulant or antiplatelet therapy.', 'Potential additive antiplatelet or anticoagulant activity, or altered anticoagulant metabolism noted in official regulatory safety guidance.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=garlic_ail&lang=eng', '{"fr": {"drug_name": "Anticoagulants et antiplaquettaires (Warfarine, Aspirine)", "description": "Consultez un professionnel de la santé et surveillez les paramètres de coagulation (RIN ou signes de saignement) lors de l''association avec un traitement anticoagulant ou antiplaquettaire. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners or protease inhibitors (Brinker 2010; Mills and Bone 2005). »)", "mechanism": "Effet antiplaquettaire ou anticoagulant additif potentiel, ou altération du métabolisme des anticoagulants signalés dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '7fc16acb-06c8-4431-84f7-112f68455e67'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '7fc16acb-06c8-4431-84f7-112f68455e67'::uuid AND lower(e.drug_name) = lower('Anticoagulants and Antiplatelets (Warfarin, Aspirin)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '105737fc-9896-4901-8453-8df16b0fe943'::uuid, 'Anticoagulants and Antiplatelets (Warfarin, Aspirin)', NULL, 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners (ASHP 2005; Franco et al. 2004; IOM 2001; Hansten et al. 1997). Consult a healthcare professional and monitor coagulation parameters (such as INR or bleeding signs) when combining with anticoagulant or antiplatelet therapy.', 'Potential additive antiplatelet or anticoagulant activity, or altered anticoagulant metabolism noted in official regulatory safety guidance.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=blueberry.bleuet2&lang=eng', '{"fr": {"drug_name": "Anticoagulants et antiplaquettaires (Warfarine, Aspirine)", "description": "Consultez un professionnel de la santé et surveillez les paramètres de coagulation (RIN ou signes de saignement) lors de l''association avec un traitement anticoagulant ou antiplaquettaire. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners (ASHP 2005; Franco et al. 2004; IOM 2001; Hansten et al. 1997). »)", "mechanism": "Effet antiplaquettaire ou anticoagulant additif potentiel, ou altération du métabolisme des anticoagulants signalés dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '105737fc-9896-4901-8453-8df16b0fe943'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '105737fc-9896-4901-8453-8df16b0fe943'::uuid AND lower(e.drug_name) = lower('Anticoagulants and Antiplatelets (Warfarin, Aspirin)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT 'fd02a72d-86b1-4b3c-8348-6586f9390971'::uuid, 'Anticoagulants and Antiplatelets (Warfarin, Aspirin)', NULL, 'moderate'::interaction_severity, 'There are theoretical reasons to suspect that cat’s claw might interact with anticoagulant, antiplatelet, and blood pressure drugs, and other supplements as well. If you take any type of medicine, talk with your health care provider before using cat’s claw or other herbal products; some herbs and medicines interact in harmful ways. Consult a healthcare professional and monitor coagulation parameters (such as INR or bleeding signs) when combining with anticoagulant or antiplatelet therapy.', 'Potential additive antiplatelet or anticoagulant activity, or altered anticoagulant metabolism noted in official regulatory safety guidance.', 'B', 'NCCIH', 'https://www.nccih.nih.gov/health/cats-claw', '{"fr": {"drug_name": "Anticoagulants et antiplaquettaires (Warfarine, Aspirine)", "description": "Consultez un professionnel de la santé et surveillez les paramètres de coagulation (RIN ou signes de saignement) lors de l''association avec un traitement anticoagulant ou antiplaquettaire. (Source officielle : NCCIH — « There are theoretical reasons to suspect that cat’s claw might interact with anticoagulant, antiplatelet, and blood pressure drugs, and other supplements as well. If you take any type of medicine, talk with your health care provider before using cat’s claw or other herbal products; some herbs and medicines interact in harmful ways. »)", "mechanism": "Effet antiplaquettaire ou anticoagulant additif potentiel, ou altération du métabolisme des anticoagulants signalés dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = 'fd02a72d-86b1-4b3c-8348-6586f9390971'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = 'fd02a72d-86b1-4b3c-8348-6586f9390971'::uuid AND lower(e.drug_name) = lower('Anticoagulants and Antiplatelets (Warfarin, Aspirin)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '81ed995f-2d7f-451d-9267-f2c0db247ba4'::uuid, 'Oral Contraceptives', NULL, 'moderate'::interaction_severity, 'Chamomile might have some of the same effects as estrogen. Preliminary studies suggest that taking chamomile along with birth control pills might decrease the effects of birth control pills. In addition, chamomile might worsen any condition that is sensitive to exposure to estrogen, such as breast or uterine cancer. Consult a healthcare practitioner before use if taking oral contraceptives or hormone-containing medications.', 'Potential hormonal or metabolic interaction with estrogen/progestin oral contraceptives noted in official regulatory monograph cautions.', 'B', 'NCCIH', 'https://www.nccih.nih.gov/health/chamomile', '{"fr": {"drug_name": "Contraceptifs oraux", "description": "Consultez un professionnel de la santé avant utilisation si vous prenez des contraceptifs oraux ou des médicaments hormonaux. (Source officielle : NCCIH — « Chamomile might have some of the same effects as estrogen. Preliminary studies suggest that taking chamomile along with birth control pills might decrease the effects of birth control pills. In addition, chamomile might worsen any condition that is sensitive to exposure to estrogen, such as breast or uterine cancer. »)", "mechanism": "Interaction hormonale ou métabolique potentielle avec les contraceptifs oraux signalée dans les précautions de la monographie officielle."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '81ed995f-2d7f-451d-9267-f2c0db247ba4'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '81ed995f-2d7f-451d-9267-f2c0db247ba4'::uuid AND lower(e.drug_name) = lower('Oral Contraceptives'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '81ed995f-2d7f-451d-9267-f2c0db247ba4'::uuid, 'Anticoagulants and Antiplatelets (Warfarin, Aspirin)', NULL, 'moderate'::interaction_severity, 'Interactions between chamomile and some drugs metabolized by the liver and warfarin (a blood thinner) have been reported, and there are theoretical reasons to suspect that chamomile might interact with other drugs as well, such as sedatives. If you take any type of medicine, talk with your health care provider before using chamomile or other herbal products; some herbs and medicines interact in harmful ways. Consult a healthcare professional and monitor coagulation parameters (such as INR or bleeding signs) when combining with anticoagulant or antiplatelet therapy.', 'Potential additive antiplatelet or anticoagulant activity, or altered anticoagulant metabolism noted in official regulatory safety guidance.', 'B', 'NCCIH', 'https://www.nccih.nih.gov/health/chamomile', '{"fr": {"drug_name": "Anticoagulants et antiplaquettaires (Warfarine, Aspirine)", "description": "Consultez un professionnel de la santé et surveillez les paramètres de coagulation (RIN ou signes de saignement) lors de l''association avec un traitement anticoagulant ou antiplaquettaire. (Source officielle : NCCIH — « Interactions between chamomile and some drugs metabolized by the liver and warfarin (a blood thinner) have been reported, and there are theoretical reasons to suspect that chamomile might interact with other drugs as well, such as sedatives. If you take any type of medicine, talk with your health care provider before using chamomile or other herbal products; some herbs and medicines interact in harmful ways. »)", "mechanism": "Effet antiplaquettaire ou anticoagulant additif potentiel, ou altération du métabolisme des anticoagulants signalés dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '81ed995f-2d7f-451d-9267-f2c0db247ba4'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '81ed995f-2d7f-451d-9267-f2c0db247ba4'::uuid AND lower(e.drug_name) = lower('Anticoagulants and Antiplatelets (Warfarin, Aspirin)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '81ed995f-2d7f-451d-9267-f2c0db247ba4'::uuid, 'Sedatives and CNS depressants', NULL, 'moderate'::interaction_severity, 'Interactions between chamomile and some drugs metabolized by the liver and warfarin (a blood thinner) have been reported, and there are theoretical reasons to suspect that chamomile might interact with other drugs as well, such as sedatives. If you take any type of medicine, talk with your health care provider before using chamomile or other herbal products; some herbs and medicines interact in harmful ways. Avoid combining with sedative or CNS-depressant medications without medical advice, and use caution when driving.', 'Potential additive central nervous system depression and drowsiness when combined with sedatives, hypnotics, or barbiturates.', 'B', 'NCCIH', 'https://www.nccih.nih.gov/health/chamomile', '{"fr": {"drug_name": "Sédatifs et dépresseurs du SNC", "description": "Évitez l''association avec des sédatifs ou dépresseurs du SNC sans avis médical et soyez prudent lors de la conduite. (Source officielle : NCCIH — « Interactions between chamomile and some drugs metabolized by the liver and warfarin (a blood thinner) have been reported, and there are theoretical reasons to suspect that chamomile might interact with other drugs as well, such as sedatives. If you take any type of medicine, talk with your health care provider before using chamomile or other herbal products; some herbs and medicines interact in harmful ways. »)", "mechanism": "Dépression additive potentielle du système nerveux central et somnolence accrue lors de l''association avec des sédatifs, hypnotiques ou barbituriques."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '81ed995f-2d7f-451d-9267-f2c0db247ba4'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '81ed995f-2d7f-451d-9267-f2c0db247ba4'::uuid AND lower(e.drug_name) = lower('Sedatives and CNS depressants'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '3b197d51-d5ad-42fd-9e7c-470d85c9fc33'::uuid, 'Corticosteroids (Prednisone)', '8640', 'moderate'::interaction_severity, 'Over a dozen publications, largely from Europe, have described clinically apparent acute liver injury attributable to greater celandine (Chelidonium majus). Liver injury typically arises after 1 to 6 months, with jaundice and moderate to marked elevations in serum aminotransferase levels. The pattern of injury is usually hepatocellular and the clinical presentation and liver histology resemble acute viral hepatitis. Immunoallergic features are uncommon, but autoantibodies may be present in low to moderate levels in many cases. The clinical syndrome, however, rarely resembles autoimmune hepatitis and usually resolves rapidly once the botanical is discontinued and without need of corticosteroid therapy. There have been no reports of greater celandine hepatotoxicity from the United States or the Americas. Consult a physician or pharmacist before combining with systemic corticosteroids.', 'Concomitant use with corticosteroids may increase the risk of potassium depletion or electrolyte imbalance, or alter immunological effects.', 'B', 'LiverTox', 'https://www.ncbi.nlm.nih.gov/books/n/livertox/Celandine/', '{"fr": {"drug_name": "Corticostéroïdes (Prednisone)", "description": "Consultez un médecin ou un pharmacien avant toute association avec des corticostéroïdes systémiques. (Source officielle : LiverTox — « Over a dozen publications, largely from Europe, have described clinically apparent acute liver injury attributable to greater celandine (Chelidonium majus). Liver injury typically arises after 1 to 6 months, with jaundice and moderate to marked elevations in serum aminotransferase levels. The pattern of injury is usually hepatocellular and the clinical presentation and liver histology resemble acute viral hepatitis. Immunoallergic features are uncommon, but autoantibodies may be present in low to moderate levels in many cases. The clinical syndrome, however, rarely resembles autoimmune hepatitis and usually resolves rapidly once the botanical is discontinued and without need of corticosteroid therapy. There have been no reports of greater celandine hepatotoxicity from the United States or the Americas. »)", "mechanism": "L''utilisation concomitante avec des corticostéroïdes peut accroître le risque d''hypokaliémie, de déséquilibre électrolytique ou d''interaction immunologique."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '3b197d51-d5ad-42fd-9e7c-470d85c9fc33'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '3b197d51-d5ad-42fd-9e7c-470d85c9fc33'::uuid AND lower(e.drug_name) = lower('Corticosteroids (Prednisone)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT 'c00cd42d-2026-488a-915f-8bcd6caa061b'::uuid, 'Anticoagulants and Antiplatelets (Warfarin, Aspirin)', NULL, 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners (Ohkawa et al. 1995; NNHPD Multi-vitamin/mineral supplements monograph). Consult a healthcare professional and monitor coagulation parameters (such as INR or bleeding signs) when combining with anticoagulant or antiplatelet therapy.', 'Potential additive antiplatelet or anticoagulant activity, or altered anticoagulant metabolism noted in official regulatory safety guidance.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=chlorella.vulgaris2&lang=eng', '{"fr": {"drug_name": "Anticoagulants et antiplaquettaires (Warfarine, Aspirine)", "description": "Consultez un professionnel de la santé et surveillez les paramètres de coagulation (RIN ou signes de saignement) lors de l''association avec un traitement anticoagulant ou antiplaquettaire. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners (Ohkawa et al. 1995; NNHPD Multi-vitamin/mineral supplements monograph). »)", "mechanism": "Effet antiplaquettaire ou anticoagulant additif potentiel, ou altération du métabolisme des anticoagulants signalés dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = 'c00cd42d-2026-488a-915f-8bcd6caa061b'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = 'c00cd42d-2026-488a-915f-8bcd6caa061b'::uuid AND lower(e.drug_name) = lower('Anticoagulants and Antiplatelets (Warfarin, Aspirin)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT 'a526cd09-13e0-4515-995a-fa0edd607c5e'::uuid, 'Anticoagulants and Antiplatelets (Warfarin, Aspirin)', NULL, 'moderate'::interaction_severity, 'Ask a healthcare practitioner/health care provider/health care professional/doctor/physician before use if you are taking medications, including blood thinners (HC 2026; Brinker 2010). Consult a healthcare professional and monitor coagulation parameters (such as INR or bleeding signs) when combining with anticoagulant or antiplatelet therapy.', 'Potential additive antiplatelet or anticoagulant activity, or altered anticoagulant metabolism noted in official regulatory safety guidance.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=citrus.bioflav.agrumes2&lang=eng', '{"fr": {"drug_name": "Anticoagulants et antiplaquettaires (Warfarine, Aspirine)", "description": "Consultez un professionnel de la santé et surveillez les paramètres de coagulation (RIN ou signes de saignement) lors de l''association avec un traitement anticoagulant ou antiplaquettaire. (Source officielle : Health Canada — « Ask a healthcare practitioner/health care provider/health care professional/doctor/physician before use if you are taking medications, including blood thinners (HC 2026; Brinker 2010). »)", "mechanism": "Effet antiplaquettaire ou anticoagulant additif potentiel, ou altération du métabolisme des anticoagulants signalés dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = 'a526cd09-13e0-4515-995a-fa0edd607c5e'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = 'a526cd09-13e0-4515-995a-fa0edd607c5e'::uuid AND lower(e.drug_name) = lower('Anticoagulants and Antiplatelets (Warfarin, Aspirin)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '8f2cd510-5691-485a-a6c3-418668085c4f'::uuid, 'Immunosuppressants', NULL, 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking medications to suppress the immune system (Albers et al. 2005). Consult a specialist before use if taking immunosuppressive therapy.', 'Immunostimulant or immunomodulatory botanicals may theoretically oppose the therapeutic action of immunosuppressive medications.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=bovine.colostrum.bovin2&lang=eng', '{"fr": {"drug_name": "Immunosuppresseurs", "description": "Consultez un médecin spécialiste avant toute utilisation sous traitement immunosuppresseur. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking medications to suppress the immune system (Albers et al. 2005). »)", "mechanism": "Les plantes immunostimulantes ou immunomodulatrices peuvent s''opposer à l''action thérapeutique des médicaments immunosuppresseurs."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '8f2cd510-5691-485a-a6c3-418668085c4f'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '8f2cd510-5691-485a-a6c3-418668085c4f'::uuid AND lower(e.drug_name) = lower('Immunosuppressants'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '63ce15dd-fea4-4910-aa7c-3b645ca56abe'::uuid, 'Anticoagulants and Antiplatelets (Warfarin, Aspirin)', NULL, 'moderate'::interaction_severity, 'Hepatotoxicity from comfrey is now rare, as it is widely accepted as being toxic when taken internally and oral formulations are restricted or banned in most countries. Management should be directed at limiting further injury and specific treatment of complications (ascites, variceal bleeding). Anticoagulants have not been shown to be beneficial. Difibrotide (a complex mixture of single stranded DNA prepared from pig intestine) has recently been approved for therapy of severe SOS accompanied by renal or pulmonary failure occurring after myeloablation for hematopoietic cell transplantation. More extensive description of sinusoidal obstruction syndrome and its management are given in the introductory section and in discussion of the antineoplastic alkylating agents. Consult a healthcare professional and monitor coagulation parameters (such as INR or bleeding signs) when combining with anticoagulant or antiplatelet therapy.', 'Potential additive antiplatelet or anticoagulant activity, or altered anticoagulant metabolism noted in official regulatory safety guidance.', 'B', 'LiverTox', 'https://www.ncbi.nlm.nih.gov/books/n/livertox/Comfrey/', '{"fr": {"drug_name": "Anticoagulants et antiplaquettaires (Warfarine, Aspirine)", "description": "Consultez un professionnel de la santé et surveillez les paramètres de coagulation (RIN ou signes de saignement) lors de l''association avec un traitement anticoagulant ou antiplaquettaire. (Source officielle : LiverTox — « Hepatotoxicity from comfrey is now rare, as it is widely accepted as being toxic when taken internally and oral formulations are restricted or banned in most countries. Management should be directed at limiting further injury and specific treatment of complications (ascites, variceal bleeding). Anticoagulants have not been shown to be beneficial. Difibrotide (a complex mixture of single stranded DNA prepared from pig intestine) has recently been approved for therapy of severe SOS accompanied by renal or pulmonary failure occurring after myeloablation for hematopoietic cell transplantation. More extensive description of sinusoidal obstruction syndrome and its management are given in the introductory section and in discussion of the antineoplastic alkylating agents. »)", "mechanism": "Effet antiplaquettaire ou anticoagulant additif potentiel, ou altération du métabolisme des anticoagulants signalés dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '63ce15dd-fea4-4910-aa7c-3b645ca56abe'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '63ce15dd-fea4-4910-aa7c-3b645ca56abe'::uuid AND lower(e.drug_name) = lower('Anticoagulants and Antiplatelets (Warfarin, Aspirin)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT 'c88d0501-6115-4b44-94eb-02162d8268e2'::uuid, 'Antihypertensives', NULL, 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood pressure medication (Rosenfeldt et al. 2007; Singh et al. 1999). Consult a healthcare professional before use with blood pressure medications and monitor blood pressure regularly.', 'May alter blood pressure or interact additively/antagonistically with antihypertensive therapy according to regulatory monograph warnings.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=coenzyme.q10&lang=eng', '{"fr": {"drug_name": "Antihypertenseurs", "description": "Consultez un professionnel de la santé avant toute utilisation avec des médicaments contre l''hypertension et surveillez régulièrement la tension artérielle. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood pressure medication (Rosenfeldt et al. 2007; Singh et al. 1999). »)", "mechanism": "Peut modifier la tension artérielle ou interagir avec un traitement antihypertenseur selon les avertissements de la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = 'c88d0501-6115-4b44-94eb-02162d8268e2'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = 'c88d0501-6115-4b44-94eb-02162d8268e2'::uuid AND lower(e.drug_name) = lower('Antihypertensives'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT 'c88d0501-6115-4b44-94eb-02162d8268e2'::uuid, 'Anticoagulants and Antiplatelets (Warfarin, Aspirin)', NULL, 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners (Engelsen et al. 2003; Landbo and Almdal 1998; Spigset 1994). Consult a healthcare professional and monitor coagulation parameters (such as INR or bleeding signs) when combining with anticoagulant or antiplatelet therapy.', 'Potential additive antiplatelet or anticoagulant activity, or altered anticoagulant metabolism noted in official regulatory safety guidance.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=coenzyme.q10&lang=eng', '{"fr": {"drug_name": "Anticoagulants et antiplaquettaires (Warfarine, Aspirine)", "description": "Consultez un professionnel de la santé et surveillez les paramètres de coagulation (RIN ou signes de saignement) lors de l''association avec un traitement anticoagulant ou antiplaquettaire. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners (Engelsen et al. 2003; Landbo and Almdal 1998; Spigset 1994). »)", "mechanism": "Effet antiplaquettaire ou anticoagulant additif potentiel, ou altération du métabolisme des anticoagulants signalés dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = 'c88d0501-6115-4b44-94eb-02162d8268e2'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = 'c88d0501-6115-4b44-94eb-02162d8268e2'::uuid AND lower(e.drug_name) = lower('Anticoagulants and Antiplatelets (Warfarin, Aspirin)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT 'fd1a8fdb-1a2e-4f82-940c-2931c03706a3'::uuid, 'Phenelzine (MAOIs)', '8123', 'contraindicated'::interaction_severity, 'Do not use yohimbe if you are taking types of antidepressant medications called monoamine oxidase inhibitors or tricyclic antidepressants. Yohimbe can interact with these medications. If you take any type of medicine, talk with your health care provider before using yohimbe or other herbal products; some herbs and medicines interact in harmful ways. Avoid concomitant use with monoamine oxidase inhibitors (MAOIs) or within 14 days of discontinuing MAOI therapy.', 'Potential sympathomimetic or serotonergic interaction with monoamine oxidase inhibitors (MAOIs) documented in regulatory safety warnings.', 'B', 'NCCIH', 'https://www.nccih.nih.gov/health/yohimbe', '{"fr": {"drug_name": "Phénelzine (IMAO)", "description": "Évitez l''utilisation concomitante avec des inhibiteurs de la monoamine-oxydase (IMAO) ou dans les 14 jours suivant l''arrêt d''un IMAO. (Source officielle : NCCIH — « Do not use yohimbe if you are taking types of antidepressant medications called monoamine oxidase inhibitors or tricyclic antidepressants. Yohimbe can interact with these medications. If you take any type of medicine, talk with your health care provider before using yohimbe or other herbal products; some herbs and medicines interact in harmful ways. »)", "mechanism": "Interaction sympathomimétique ou sérotoninergique potentielle avec les inhibiteurs de la monoamine-oxydase (IMAO) documentée par les autorités réglementaires."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = 'fd1a8fdb-1a2e-4f82-940c-2931c03706a3'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = 'fd1a8fdb-1a2e-4f82-940c-2931c03706a3'::uuid AND lower(e.drug_name) = lower('Phenelzine (MAOIs)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT 'fd1a8fdb-1a2e-4f82-940c-2931c03706a3'::uuid, 'Antidepressants (SSRIs)', NULL, 'contraindicated'::interaction_severity, 'Do not use yohimbe if you are taking types of antidepressant medications called monoamine oxidase inhibitors or tricyclic antidepressants. Yohimbe can interact with these medications. If you take any type of medicine, talk with your health care provider before using yohimbe or other herbal products; some herbs and medicines interact in harmful ways. Consult a prescribing clinician before combining with SSRIs, SNRIs, or other serotonergic antidepressant medications.', 'Potential pharmacodynamic or serotonergic interaction with antidepressant medications noted in official monograph safety guidance.', 'B', 'NCCIH', 'https://www.nccih.nih.gov/health/yohimbe', '{"fr": {"drug_name": "Antidépresseurs (ISRS)", "description": "Consultez un médecin prescripteur avant d''associer ce produit à des ISRS, IRSN ou autres antidépresseurs sérotoninergiques. (Source officielle : NCCIH — « Do not use yohimbe if you are taking types of antidepressant medications called monoamine oxidase inhibitors or tricyclic antidepressants. Yohimbe can interact with these medications. If you take any type of medicine, talk with your health care provider before using yohimbe or other herbal products; some herbs and medicines interact in harmful ways. »)", "mechanism": "Interaction pharmacodynamique ou sérotoninergique potentielle avec les médicaments antidépresseurs signalée dans la monographie officielle."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = 'fd1a8fdb-1a2e-4f82-940c-2931c03706a3'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = 'fd1a8fdb-1a2e-4f82-940c-2931c03706a3'::uuid AND lower(e.drug_name) = lower('Antidepressants (SSRIs)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT 'f5c98173-ea77-4355-a4f0-6fca9bc0f04c'::uuid, 'Anticoagulants and Antiplatelets (Warfarin, Aspirin)', NULL, 'moderate'::interaction_severity, 'There is conflicting evidence about whether cranberry interacts with the anticoagulant (blood thinner) warfarin. If you take warfarin or any other medicine, talk with your health care provider before using cranberry or other herbal products; some herbs and medicines interact in harmful ways. Consult a healthcare professional and monitor coagulation parameters (such as INR or bleeding signs) when combining with anticoagulant or antiplatelet therapy.', 'Potential additive antiplatelet or anticoagulant activity, or altered anticoagulant metabolism noted in official regulatory safety guidance.', 'B', 'NCCIH', 'https://www.nccih.nih.gov/health/cranberry', '{"fr": {"drug_name": "Anticoagulants et antiplaquettaires (Warfarine, Aspirine)", "description": "Consultez un professionnel de la santé et surveillez les paramètres de coagulation (RIN ou signes de saignement) lors de l''association avec un traitement anticoagulant ou antiplaquettaire. (Source officielle : NCCIH — « There is conflicting evidence about whether cranberry interacts with the anticoagulant (blood thinner) warfarin. If you take warfarin or any other medicine, talk with your health care provider before using cranberry or other herbal products; some herbs and medicines interact in harmful ways. »)", "mechanism": "Effet antiplaquettaire ou anticoagulant additif potentiel, ou altération du métabolisme des anticoagulants signalés dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = 'f5c98173-ea77-4355-a4f0-6fca9bc0f04c'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = 'f5c98173-ea77-4355-a4f0-6fca9bc0f04c'::uuid AND lower(e.drug_name) = lower('Anticoagulants and Antiplatelets (Warfarin, Aspirin)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT 'b5dfff84-7a03-4ac9-bf68-322564b22bdd'::uuid, 'Digoxin', '3407', 'moderate'::interaction_severity, 'Interactions (4.5): with other medicinal products and other forms of interaction Well-established use Traditional use Hypokalaemia (resulting from long-term laxative abuse) potentiates the action of cardiac glycosides and interacts with antiarrhythmic medicinal products. Concomitant use with diuretics, adrenocorticosteroids and liquorice root may enhance loss of potassium. Do not combine with digoxin or other cardiac glycosides without direct medical supervision.', 'Potential cardiac glycoside sensitivity shift (including via potassium depletion or P-glycoprotein/inotropic effects) noted in regulatory safety warnings.', 'B', 'European Medicines Agency (HMPC)', 'https://www.ema.europa.eu/en/documents/herbal-monograph/final-european-union-herbal-monograph-rheum-palmatum-l-and-rheum-officinale-baillon-radix-revision-1_en.pdf', '{"fr": {"drug_name": "Digoxine", "description": "Ne pas associer à la digoxine ou à d''autres glycosides cardiaques sans surveillance médicale directe. (Source officielle : European Medicines Agency (HMPC) — « Interactions (4.5): with other medicinal products and other forms of interaction Well-established use Traditional use Hypokalaemia (resulting from long-term laxative abuse) potentiates the action of cardiac glycosides and interacts with antiarrhythmic medicinal products. Concomitant use with diuretics, adrenocorticosteroids and liquorice root may enhance loss of potassium. »)", "mechanism": "Modification potentielle de la sensibilité aux glycosides cardiaques (notamment par déplétion potassique ou effet inotrope/P-gp) signalée dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = 'b5dfff84-7a03-4ac9-bf68-322564b22bdd'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = 'b5dfff84-7a03-4ac9-bf68-322564b22bdd'::uuid AND lower(e.drug_name) = lower('Digoxin'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '9c8f0728-06a2-4630-b8ea-778eb320ec80'::uuid, 'Anticoagulants and Antiplatelets (Warfarin, Aspirin)', NULL, 'moderate'::interaction_severity, 'There are theoretical reasons to suspect that dandelion might interact with antidiabetes, anticoagulant, antiplatelet, and water pill drugs, among others. If you take any type of medicine or supplements, talk with your health care provider before using dandelion or other herbal products; some herbs and medicines interact in harmful ways. Consult a healthcare professional and monitor coagulation parameters (such as INR or bleeding signs) when combining with anticoagulant or antiplatelet therapy.', 'Potential additive antiplatelet or anticoagulant activity, or altered anticoagulant metabolism noted in official regulatory safety guidance.', 'B', 'NCCIH', 'https://www.nccih.nih.gov/health/dandelion', '{"fr": {"drug_name": "Anticoagulants et antiplaquettaires (Warfarine, Aspirine)", "description": "Consultez un professionnel de la santé et surveillez les paramètres de coagulation (RIN ou signes de saignement) lors de l''association avec un traitement anticoagulant ou antiplaquettaire. (Source officielle : NCCIH — « There are theoretical reasons to suspect that dandelion might interact with antidiabetes, anticoagulant, antiplatelet, and water pill drugs, among others. If you take any type of medicine or supplements, talk with your health care provider before using dandelion or other herbal products; some herbs and medicines interact in harmful ways. »)", "mechanism": "Effet antiplaquettaire ou anticoagulant additif potentiel, ou altération du métabolisme des anticoagulants signalés dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '9c8f0728-06a2-4630-b8ea-778eb320ec80'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '9c8f0728-06a2-4630-b8ea-778eb320ec80'::uuid AND lower(e.drug_name) = lower('Anticoagulants and Antiplatelets (Warfarin, Aspirin)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '086fbccf-1169-4a4c-b00e-b49710a2b30c'::uuid, 'Anticoagulants and Antiplatelets (Warfarin, Aspirin)', NULL, 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician prior to use if you are taking any medications including blood thinners, birth control pills or hormone therapy (NS 2021; Brinker 2010; WHO 2002). Consult a healthcare professional and monitor coagulation parameters (such as INR or bleeding signs) when combining with anticoagulant or antiplatelet therapy.', 'Potential additive antiplatelet or anticoagulant activity, or altered anticoagulant metabolism noted in official regulatory safety guidance.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=angelica.sinensis2&lang=eng', '{"fr": {"drug_name": "Anticoagulants et antiplaquettaires (Warfarine, Aspirine)", "description": "Consultez un professionnel de la santé et surveillez les paramètres de coagulation (RIN ou signes de saignement) lors de l''association avec un traitement anticoagulant ou antiplaquettaire. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician prior to use if you are taking any medications including blood thinners, birth control pills or hormone therapy (NS 2021; Brinker 2010; WHO 2002). »)", "mechanism": "Effet antiplaquettaire ou anticoagulant additif potentiel, ou altération du métabolisme des anticoagulants signalés dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '086fbccf-1169-4a4c-b00e-b49710a2b30c'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '086fbccf-1169-4a4c-b00e-b49710a2b30c'::uuid AND lower(e.drug_name) = lower('Anticoagulants and Antiplatelets (Warfarin, Aspirin)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '086fbccf-1169-4a4c-b00e-b49710a2b30c'::uuid, 'Oral Contraceptives', NULL, 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician prior to use if you are taking any medications including blood thinners, birth control pills or hormone therapy (NS 2021; Brinker 2010; WHO 2002). Consult a healthcare practitioner before use if taking oral contraceptives or hormone-containing medications.', 'Potential hormonal or metabolic interaction with estrogen/progestin oral contraceptives noted in official regulatory monograph cautions.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=angelica.sinensis2&lang=eng', '{"fr": {"drug_name": "Contraceptifs oraux", "description": "Consultez un professionnel de la santé avant utilisation si vous prenez des contraceptifs oraux ou des médicaments hormonaux. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician prior to use if you are taking any medications including blood thinners, birth control pills or hormone therapy (NS 2021; Brinker 2010; WHO 2002). »)", "mechanism": "Interaction hormonale ou métabolique potentielle avec les contraceptifs oraux signalée dans les précautions de la monographie officielle."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '086fbccf-1169-4a4c-b00e-b49710a2b30c'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '086fbccf-1169-4a4c-b00e-b49710a2b30c'::uuid AND lower(e.drug_name) = lower('Oral Contraceptives'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '086fbccf-1169-4a4c-b00e-b49710a2b30c'::uuid, 'Hormone replacement therapy', NULL, 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician prior to use if you are taking any medications including blood thinners, birth control pills or hormone therapy (NS 2021; Brinker 2010; WHO 2002). Consult a healthcare professional before combining with hormone replacement therapy.', 'Potential phytoestrogenic, dopaminergic, or endocrine receptor interaction with hormone replacement therapy noted in regulatory monograph warnings.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=angelica.sinensis2&lang=eng', '{"fr": {"drug_name": "Hormonothérapie substitutive", "description": "Consultez un professionnel de la santé avant d''associer ce produit à une hormonothérapie substitutive. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician prior to use if you are taking any medications including blood thinners, birth control pills or hormone therapy (NS 2021; Brinker 2010; WHO 2002). »)", "mechanism": "Interaction phytoœstrogénique, dopaminergique ou endocrinienne potentielle avec l''hormonothérapie substitutive signalée dans la monographie officielle."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '086fbccf-1169-4a4c-b00e-b49710a2b30c'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '086fbccf-1169-4a4c-b00e-b49710a2b30c'::uuid AND lower(e.drug_name) = lower('Hormone replacement therapy'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '806fb200-f937-41e9-bf61-bdcd9814a679'::uuid, 'Immunosuppressants', NULL, 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking medications to suppress the immune system (Brinker 2010; Mills and Bone 2005). Consult a specialist before use if taking immunosuppressive therapy.', 'Immunostimulant or immunomodulatory botanicals may theoretically oppose the therapeutic action of immunosuppressive medications.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=echinacea.angustifolia2&lang=eng', '{"fr": {"drug_name": "Immunosuppresseurs", "description": "Consultez un médecin spécialiste avant toute utilisation sous traitement immunosuppresseur. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking medications to suppress the immune system (Brinker 2010; Mills and Bone 2005). »)", "mechanism": "Les plantes immunostimulantes ou immunomodulatrices peuvent s''opposer à l''action thérapeutique des médicaments immunosuppresseurs."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '806fb200-f937-41e9-bf61-bdcd9814a679'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '806fb200-f937-41e9-bf61-bdcd9814a679'::uuid AND lower(e.drug_name) = lower('Immunosuppressants'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '7168846c-d722-49cd-8460-177ee4e2a45f'::uuid, 'Immunosuppressants', NULL, 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking medications to suppress the immune system (Brinker 2010; Mills et al. 2006). Consult a specialist before use if taking immunosuppressive therapy.', 'Immunostimulant or immunomodulatory botanicals may theoretically oppose the therapeutic action of immunosuppressive medications.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=echinacea.pallida2&lang=eng', '{"fr": {"drug_name": "Immunosuppresseurs", "description": "Consultez un médecin spécialiste avant toute utilisation sous traitement immunosuppresseur. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking medications to suppress the immune system (Brinker 2010; Mills et al. 2006). »)", "mechanism": "Les plantes immunostimulantes ou immunomodulatrices peuvent s''opposer à l''action thérapeutique des médicaments immunosuppresseurs."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '7168846c-d722-49cd-8460-177ee4e2a45f'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '7168846c-d722-49cd-8460-177ee4e2a45f'::uuid AND lower(e.drug_name) = lower('Immunosuppressants'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '9b8efe87-87a8-4c3a-9b2d-1ac983463472'::uuid, 'Levothyroxine (Synthroid)', '10582', 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you have asthma, diabetes, glaucoma, heart disease, high blood pressure, kidney disease, difficulty urinating, thyroid disease, seizure disorders, or any other serious medical condition (US FDA 2022; Brinker 2010; Hackman et al. 2006; Mills and Bone 2005; Bensky et al. 2004; Coffey et al. 2004; Greenway et al. 2004; Haller et al. 2004; Hioki et al. 2004; Mehendale et al. 2004; Hoffman 2003; Williamson 2003; Boozer et al. 2002; Boozer et al. 2001; Blumenthal et al. 2000; Kalman et al. 2000; BHP 1983). Consult a physician before use with thyroid medications and monitor thyroid function tests if combined.', 'Potential interference with thyroid hormone replacement or thyroid function noted in regulatory safety guidance.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=ephedra2&lang=eng', '{"fr": {"drug_name": "Lévothyroxine (Synthroid)", "description": "Consultez un médecin avant toute association avec des médicaments thyroïdiens et surveillez le bilan thyroïdien. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you have asthma, diabetes, glaucoma, heart disease, high blood pressure, kidney disease, difficulty urinating, thyroid disease, seizure disorders, or any other serious medical condition (US FDA 2022; Brinker 2010; Hackman et al. 2006; Mills and Bone 2005; Bensky et al. 2004; Coffey et al. 2004; Greenway et al. 2004; Haller et al. 2004; Hioki et al. 2004; Mehendale et al. 2004; Hoffman 2003; Williamson 2003; Boozer et al. 2002; Boozer et al. 2001; Blumenthal et al. 2000; Kalman et al. 2000; BHP 1983). »)", "mechanism": "Interférence potentielle avec le traitement substitutif par hormone thyroïdienne ou la fonction thyroïdienne signalée dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '9b8efe87-87a8-4c3a-9b2d-1ac983463472'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '9b8efe87-87a8-4c3a-9b2d-1ac983463472'::uuid AND lower(e.drug_name) = lower('Levothyroxine (Synthroid)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT 'cfb568ce-838d-4a4f-ae83-ee3e6e1e4fa9'::uuid, 'Anticoagulants and Antiplatelets (Warfarin, Aspirin)', NULL, 'moderate'::interaction_severity, 'Despite being widely used, fenugreek has not been implicated in cases of clinically apparent liver injury and, in prospective studies, has had no effect on serum enzyme levels. In vitro studies have demonstrated hepatoprotective activity of fenugreek extracts in several animal models. Because of the high fiber content, estrogenic and coumadin-like effects of fenugreek, it has a potential to cause herb-drug interactions particularly if taken in high doses with antiplatelet drugs and warfarin. Consult a healthcare professional and monitor coagulation parameters (such as INR or bleeding signs) when combining with anticoagulant or antiplatelet therapy.', 'Potential additive antiplatelet or anticoagulant activity, or altered anticoagulant metabolism noted in official regulatory safety guidance.', 'B', 'LiverTox', 'https://www.ncbi.nlm.nih.gov/books/n/livertox/Fenugreek/', '{"fr": {"drug_name": "Anticoagulants et antiplaquettaires (Warfarine, Aspirine)", "description": "Consultez un professionnel de la santé et surveillez les paramètres de coagulation (RIN ou signes de saignement) lors de l''association avec un traitement anticoagulant ou antiplaquettaire. (Source officielle : LiverTox — « Despite being widely used, fenugreek has not been implicated in cases of clinically apparent liver injury and, in prospective studies, has had no effect on serum enzyme levels. In vitro studies have demonstrated hepatoprotective activity of fenugreek extracts in several animal models. Because of the high fiber content, estrogenic and coumadin-like effects of fenugreek, it has a potential to cause herb-drug interactions particularly if taken in high doses with antiplatelet drugs and warfarin. »)", "mechanism": "Effet antiplaquettaire ou anticoagulant additif potentiel, ou altération du métabolisme des anticoagulants signalés dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = 'cfb568ce-838d-4a4f-ae83-ee3e6e1e4fa9'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = 'cfb568ce-838d-4a4f-ae83-ee3e6e1e4fa9'::uuid AND lower(e.drug_name) = lower('Anticoagulants and Antiplatelets (Warfarin, Aspirin)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '7a10a760-d74a-4942-a464-ed352468cbdd'::uuid, 'Anticoagulants and Antiplatelets (Warfarin, Aspirin)', NULL, 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners (Brinker 2010; Biggs et al. 1982). Consult a healthcare professional and monitor coagulation parameters (such as INR or bleeding signs) when combining with anticoagulant or antiplatelet therapy.', 'Potential additive antiplatelet or anticoagulant activity, or altered anticoagulant metabolism noted in official regulatory safety guidance.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=feverfew2&lang=eng', '{"fr": {"drug_name": "Anticoagulants et antiplaquettaires (Warfarine, Aspirine)", "description": "Consultez un professionnel de la santé et surveillez les paramètres de coagulation (RIN ou signes de saignement) lors de l''association avec un traitement anticoagulant ou antiplaquettaire. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners (Brinker 2010; Biggs et al. 1982). »)", "mechanism": "Effet antiplaquettaire ou anticoagulant additif potentiel, ou altération du métabolisme des anticoagulants signalés dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '7a10a760-d74a-4942-a464-ed352468cbdd'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '7a10a760-d74a-4942-a464-ed352468cbdd'::uuid AND lower(e.drug_name) = lower('Anticoagulants and Antiplatelets (Warfarin, Aspirin)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '53e75b74-5707-4e2f-8c11-6eabd17d3248'::uuid, 'Anticoagulants and Antiplatelets (Warfarin, Aspirin)', NULL, 'moderate'::interaction_severity, 'There are theoretical reasons to suspect that flaxseed or flaxseed oil might interact with other drugs, such as anticoagulant or antiplatelet drugs. If you take any type of medicine, talk with your health care provider before using flaxseed, flaxseed oil, or other herbal products; some herbs and medicines interact in harmful ways. Consult a healthcare professional and monitor coagulation parameters (such as INR or bleeding signs) when combining with anticoagulant or antiplatelet therapy.', 'Potential additive antiplatelet or anticoagulant activity, or altered anticoagulant metabolism noted in official regulatory safety guidance.', 'B', 'NCCIH', 'https://www.nccih.nih.gov/health/flaxseed-and-flaxseed-oil', '{"fr": {"drug_name": "Anticoagulants et antiplaquettaires (Warfarine, Aspirine)", "description": "Consultez un professionnel de la santé et surveillez les paramètres de coagulation (RIN ou signes de saignement) lors de l''association avec un traitement anticoagulant ou antiplaquettaire. (Source officielle : NCCIH — « There are theoretical reasons to suspect that flaxseed or flaxseed oil might interact with other drugs, such as anticoagulant or antiplatelet drugs. If you take any type of medicine, talk with your health care provider before using flaxseed, flaxseed oil, or other herbal products; some herbs and medicines interact in harmful ways. »)", "mechanism": "Effet antiplaquettaire ou anticoagulant additif potentiel, ou altération du métabolisme des anticoagulants signalés dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '53e75b74-5707-4e2f-8c11-6eabd17d3248'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '53e75b74-5707-4e2f-8c11-6eabd17d3248'::uuid AND lower(e.drug_name) = lower('Anticoagulants and Antiplatelets (Warfarin, Aspirin)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '57cb0a48-94e1-4307-852a-48c4c19ec8c0'::uuid, 'Corticosteroids (Prednisone)', '8640', 'moderate'::interaction_severity, 'Hepatotoxicity from Polygonum multiflorum is usually self-limited but can be prolonged and is occasionally fatal. Recurrence with restarting the herb is common and rechallenge should be avoided. There is little evidence for cross sensitivity to the hepatotoxic effects of other herbal medications. Use of corticosteroids has not been reported to be effective. Consult a physician or pharmacist before combining with systemic corticosteroids.', 'Concomitant use with corticosteroids may increase the risk of potassium depletion or electrolyte imbalance, or alter immunological effects.', 'B', 'LiverTox', 'https://www.ncbi.nlm.nih.gov/books/n/livertox/ShouWuPian/', '{"fr": {"drug_name": "Corticostéroïdes (Prednisone)", "description": "Consultez un médecin ou un pharmacien avant toute association avec des corticostéroïdes systémiques. (Source officielle : LiverTox — « Hepatotoxicity from Polygonum multiflorum is usually self-limited but can be prolonged and is occasionally fatal. Recurrence with restarting the herb is common and rechallenge should be avoided. There is little evidence for cross sensitivity to the hepatotoxic effects of other herbal medications. Use of corticosteroids has not been reported to be effective. »)", "mechanism": "L''utilisation concomitante avec des corticostéroïdes peut accroître le risque d''hypokaliémie, de déséquilibre électrolytique ou d''interaction immunologique."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '57cb0a48-94e1-4307-852a-48c4c19ec8c0'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '57cb0a48-94e1-4307-852a-48c4c19ec8c0'::uuid AND lower(e.drug_name) = lower('Corticosteroids (Prednisone)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '11ae2d2d-67a2-48a0-aa5e-b077003339f3'::uuid, 'Corticosteroids (Prednisone)', '8640', 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking heart medications, corticosteroids, diuretics, or other health products that may contribute to electrolyte imbalance (EMA 2020; Brinker 2010; WHO 2002; Blumenthal et al. 2000). Consult a physician or pharmacist before combining with systemic corticosteroids.', 'Concomitant use with corticosteroids may increase the risk of potassium depletion or electrolyte imbalance, or alter immunological effects.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=cascara.sagrada2&lang=eng', '{"fr": {"drug_name": "Corticostéroïdes (Prednisone)", "description": "Consultez un médecin ou un pharmacien avant toute association avec des corticostéroïdes systémiques. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking heart medications, corticosteroids, diuretics, or other health products that may contribute to electrolyte imbalance (EMA 2020; Brinker 2010; WHO 2002; Blumenthal et al. 2000). »)", "mechanism": "L''utilisation concomitante avec des corticostéroïdes peut accroître le risque d''hypokaliémie, de déséquilibre électrolytique ou d''interaction immunologique."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '11ae2d2d-67a2-48a0-aa5e-b077003339f3'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '11ae2d2d-67a2-48a0-aa5e-b077003339f3'::uuid AND lower(e.drug_name) = lower('Corticosteroids (Prednisone)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '11ae2d2d-67a2-48a0-aa5e-b077003339f3'::uuid, 'Digoxin', '3407', 'moderate'::interaction_severity, 'Interactions (4.5): with other medicinal products and other forms of interaction Well-established use Traditional use Hypokalaemia (resulting from long-term laxative abuse) potentiates the action of cardiac glycosides and interacts with antiarrhythmic medicinal products. Concomitant use with diuretics, adrenocorticosteroids and liquorice root may enhance loss of potassium. Do not combine with digoxin or other cardiac glycosides without direct medical supervision.', 'Potential cardiac glycoside sensitivity shift (including via potassium depletion or P-glycoprotein/inotropic effects) noted in regulatory safety warnings.', 'B', 'European Medicines Agency (HMPC)', 'https://www.ema.europa.eu/en/documents/herbal-monograph/final-european-union-herbal-monograph-rhamnus-purshiana-dc-cortex-revision-1_en.pdf', '{"fr": {"drug_name": "Digoxine", "description": "Ne pas associer à la digoxine ou à d''autres glycosides cardiaques sans surveillance médicale directe. (Source officielle : European Medicines Agency (HMPC) — « Interactions (4.5): with other medicinal products and other forms of interaction Well-established use Traditional use Hypokalaemia (resulting from long-term laxative abuse) potentiates the action of cardiac glycosides and interacts with antiarrhythmic medicinal products. Concomitant use with diuretics, adrenocorticosteroids and liquorice root may enhance loss of potassium. »)", "mechanism": "Modification potentielle de la sensibilité aux glycosides cardiaques (notamment par déplétion potassique ou effet inotrope/P-gp) signalée dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '11ae2d2d-67a2-48a0-aa5e-b077003339f3'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '11ae2d2d-67a2-48a0-aa5e-b077003339f3'::uuid AND lower(e.drug_name) = lower('Digoxin'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT 'b0d5cfd1-4851-40d6-89d2-f529e8d7f8f0'::uuid, 'Anticoagulants and Antiplatelets (Warfarin, Aspirin)', NULL, 'moderate'::interaction_severity, 'Taking garlic supplements may increase the risk of bleeding. If you take garlic supplements, make sure to tell your health care providers. This is especially important if you are going to have surgery or if you take medicines, such as anticoagulants or aspirin, that may also affect bleeding. Consult a healthcare professional and monitor coagulation parameters (such as INR or bleeding signs) when combining with anticoagulant or antiplatelet therapy.', 'Potential additive antiplatelet or anticoagulant activity, or altered anticoagulant metabolism noted in official regulatory safety guidance.', 'B', 'NCCIH', 'https://www.nccih.nih.gov/health/garlic', '{"fr": {"drug_name": "Anticoagulants et antiplaquettaires (Warfarine, Aspirine)", "description": "Consultez un professionnel de la santé et surveillez les paramètres de coagulation (RIN ou signes de saignement) lors de l''association avec un traitement anticoagulant ou antiplaquettaire. (Source officielle : NCCIH — « Taking garlic supplements may increase the risk of bleeding. If you take garlic supplements, make sure to tell your health care providers. This is especially important if you are going to have surgery or if you take medicines, such as anticoagulants or aspirin, that may also affect bleeding. »)", "mechanism": "Effet antiplaquettaire ou anticoagulant additif potentiel, ou altération du métabolisme des anticoagulants signalés dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = 'b0d5cfd1-4851-40d6-89d2-f529e8d7f8f0'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = 'b0d5cfd1-4851-40d6-89d2-f529e8d7f8f0'::uuid AND lower(e.drug_name) = lower('Anticoagulants and Antiplatelets (Warfarin, Aspirin)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '6090bbdd-bb3f-44db-980c-616e279cd4c0'::uuid, 'Anticoagulants and Antiplatelets (Warfarin, Aspirin)', NULL, 'moderate'::interaction_severity, 'Ginkgo may increase the risk of bleeding in people who are taking anticoagulant drugs, such as warfarin. Ginkgo may also interact with other drugs.If you take any type of medicine, talk with your health care provider before using ginkgo or other herbal products; some herbs and medicines interact in harmful ways. Consult a healthcare professional and monitor coagulation parameters (such as INR or bleeding signs) when combining with anticoagulant or antiplatelet therapy.', 'Potential additive antiplatelet or anticoagulant activity, or altered anticoagulant metabolism noted in official regulatory safety guidance.', 'B', 'NCCIH', 'https://www.nccih.nih.gov/health/ginkgo', '{"fr": {"drug_name": "Anticoagulants et antiplaquettaires (Warfarine, Aspirine)", "description": "Consultez un professionnel de la santé et surveillez les paramètres de coagulation (RIN ou signes de saignement) lors de l''association avec un traitement anticoagulant ou antiplaquettaire. (Source officielle : NCCIH — « Ginkgo may increase the risk of bleeding in people who are taking anticoagulant drugs, such as warfarin. Ginkgo may also interact with other drugs.If you take any type of medicine, talk with your health care provider before using ginkgo or other herbal products; some herbs and medicines interact in harmful ways. »)", "mechanism": "Effet antiplaquettaire ou anticoagulant additif potentiel, ou altération du métabolisme des anticoagulants signalés dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '6090bbdd-bb3f-44db-980c-616e279cd4c0'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '6090bbdd-bb3f-44db-980c-616e279cd4c0'::uuid AND lower(e.drug_name) = lower('Anticoagulants and Antiplatelets (Warfarin, Aspirin)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '6ccb47ee-2221-4003-a38d-fc68add7a73b'::uuid, 'Anticoagulants and Antiplatelets (Warfarin, Aspirin)', NULL, 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking antidepressant medication, blood thinners or digoxin (Brinker 2010; Lee et al. 2008a; Dasgupta and Reyes 2005; Janetzki and Morreale 1997; Gonzalez-Seijo et al. 1995; Shader and Greenblatt 1988; Jones and Runikis 1987; Shader and Greenblatt 1985). Consult a healthcare professional and monitor coagulation parameters (such as INR or bleeding signs) when combining with anticoagulant or antiplatelet therapy.', 'Potential additive antiplatelet or anticoagulant activity, or altered anticoagulant metabolism noted in official regulatory safety guidance.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=ginseng.panax2&lang=eng', '{"fr": {"drug_name": "Anticoagulants et antiplaquettaires (Warfarine, Aspirine)", "description": "Consultez un professionnel de la santé et surveillez les paramètres de coagulation (RIN ou signes de saignement) lors de l''association avec un traitement anticoagulant ou antiplaquettaire. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking antidepressant medication, blood thinners or digoxin (Brinker 2010; Lee et al. 2008a; Dasgupta and Reyes 2005; Janetzki and Morreale 1997; Gonzalez-Seijo et al. 1995; Shader and Greenblatt 1988; Jones and Runikis 1987; Shader and Greenblatt 1985). »)", "mechanism": "Effet antiplaquettaire ou anticoagulant additif potentiel, ou altération du métabolisme des anticoagulants signalés dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '6ccb47ee-2221-4003-a38d-fc68add7a73b'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '6ccb47ee-2221-4003-a38d-fc68add7a73b'::uuid AND lower(e.drug_name) = lower('Anticoagulants and Antiplatelets (Warfarin, Aspirin)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '6ccb47ee-2221-4003-a38d-fc68add7a73b'::uuid, 'Antidepressants (SSRIs)', NULL, 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking antidepressant medication, blood thinners or digoxin (Brinker 2010; Lee et al. 2008a; Dasgupta and Reyes 2005; Janetzki and Morreale 1997; Gonzalez-Seijo et al. 1995; Shader and Greenblatt 1988; Jones and Runikis 1987; Shader and Greenblatt 1985). Consult a prescribing clinician before combining with SSRIs, SNRIs, or other serotonergic antidepressant medications.', 'Potential pharmacodynamic or serotonergic interaction with antidepressant medications noted in official monograph safety guidance.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=ginseng.panax2&lang=eng', '{"fr": {"drug_name": "Antidépresseurs (ISRS)", "description": "Consultez un médecin prescripteur avant d''associer ce produit à des ISRS, IRSN ou autres antidépresseurs sérotoninergiques. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking antidepressant medication, blood thinners or digoxin (Brinker 2010; Lee et al. 2008a; Dasgupta and Reyes 2005; Janetzki and Morreale 1997; Gonzalez-Seijo et al. 1995; Shader and Greenblatt 1988; Jones and Runikis 1987; Shader and Greenblatt 1985). »)", "mechanism": "Interaction pharmacodynamique ou sérotoninergique potentielle avec les médicaments antidépresseurs signalée dans la monographie officielle."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '6ccb47ee-2221-4003-a38d-fc68add7a73b'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '6ccb47ee-2221-4003-a38d-fc68add7a73b'::uuid AND lower(e.drug_name) = lower('Antidepressants (SSRIs)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '6ccb47ee-2221-4003-a38d-fc68add7a73b'::uuid, 'Digoxin', '3407', 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking antidepressant medication, blood thinners or digoxin (Brinker 2010; Lee et al. 2008a; Dasgupta and Reyes 2005; Janetzki and Morreale 1997; Gonzalez-Seijo et al. 1995; Shader and Greenblatt 1988; Jones and Runikis 1987; Shader and Greenblatt 1985). Do not combine with digoxin or other cardiac glycosides without direct medical supervision.', 'Potential cardiac glycoside sensitivity shift (including via potassium depletion or P-glycoprotein/inotropic effects) noted in regulatory safety warnings.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=ginseng.panax2&lang=eng', '{"fr": {"drug_name": "Digoxine", "description": "Ne pas associer à la digoxine ou à d''autres glycosides cardiaques sans surveillance médicale directe. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking antidepressant medication, blood thinners or digoxin (Brinker 2010; Lee et al. 2008a; Dasgupta and Reyes 2005; Janetzki and Morreale 1997; Gonzalez-Seijo et al. 1995; Shader and Greenblatt 1988; Jones and Runikis 1987; Shader and Greenblatt 1985). »)", "mechanism": "Modification potentielle de la sensibilité aux glycosides cardiaques (notamment par déplétion potassique ou effet inotrope/P-gp) signalée dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '6ccb47ee-2221-4003-a38d-fc68add7a73b'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '6ccb47ee-2221-4003-a38d-fc68add7a73b'::uuid AND lower(e.drug_name) = lower('Digoxin'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT 'e6e4c873-c1c5-4bbb-be14-10e6e7603c1b'::uuid, 'Antidepressants (SSRIs)', NULL, 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking carbidopa or health products with serotonergic activity such as mood balance supplements, cough medication containing dextromethorphan, pain killers or medications for nausea or migraine (Mayo Clinic Staff 2022; Patel and Marzella 2017; Turner et al 2006). Consult a prescribing clinician before combining with SSRIs, SNRIs, or other serotonergic antidepressant medications.', 'Potential pharmacodynamic or serotonergic interaction with antidepressant medications noted in official monograph safety guidance.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=5htp&lang=eng', '{"fr": {"drug_name": "Antidépresseurs (ISRS)", "description": "Consultez un médecin prescripteur avant d''associer ce produit à des ISRS, IRSN ou autres antidépresseurs sérotoninergiques. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking carbidopa or health products with serotonergic activity such as mood balance supplements, cough medication containing dextromethorphan, pain killers or medications for nausea or migraine (Mayo Clinic Staff 2022; Patel and Marzella 2017; Turner et al 2006). »)", "mechanism": "Interaction pharmacodynamique ou sérotoninergique potentielle avec les médicaments antidépresseurs signalée dans la monographie officielle."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = 'e6e4c873-c1c5-4bbb-be14-10e6e7603c1b'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = 'e6e4c873-c1c5-4bbb-be14-10e6e7603c1b'::uuid AND lower(e.drug_name) = lower('Antidepressants (SSRIs)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '7cb34545-86cd-446e-9dba-ab0a179dc552'::uuid, 'Antihypertensives', NULL, 'moderate'::interaction_severity, 'are taking any heart or blood pressure medication (Rai et al. 1997; Agrawal et al. 1996). Consult a healthcare professional before use with blood pressure medications and monitor blood pressure regularly.', 'May alter blood pressure or interact additively/antagonistically with antihypertensive therapy according to regulatory monograph warnings.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=ocimum.tenuliflorum.leaf.feuille2&lang=eng', '{"fr": {"drug_name": "Antihypertenseurs", "description": "Consultez un professionnel de la santé avant toute utilisation avec des médicaments contre l''hypertension et surveillez régulièrement la tension artérielle. (Source officielle : Health Canada — « are taking any heart or blood pressure medication (Rai et al. 1997; Agrawal et al. 1996). »)", "mechanism": "Peut modifier la tension artérielle ou interagir avec un traitement antihypertenseur selon les avertissements de la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '7cb34545-86cd-446e-9dba-ab0a179dc552'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '7cb34545-86cd-446e-9dba-ab0a179dc552'::uuid AND lower(e.drug_name) = lower('Antihypertensives'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '0daccc19-6ba3-487e-a1a7-3c6234127a7f'::uuid, 'Sedatives and CNS depressants', NULL, 'moderate'::interaction_severity, 'See also Drug Class: Sedatives and Hypnotics, Herbals Avoid combining with sedative or CNS-depressant medications without medical advice, and use caution when driving.', 'Potential additive central nervous system depression and drowsiness when combined with sedatives, hypnotics, or barbiturates.', 'B', 'LiverTox', 'https://www.ncbi.nlm.nih.gov/books/n/livertox/Hops/', '{"fr": {"drug_name": "Sédatifs et dépresseurs du SNC", "description": "Évitez l''association avec des sédatifs ou dépresseurs du SNC sans avis médical et soyez prudent lors de la conduite. (Source officielle : LiverTox — « See also Drug Class: Sedatives and Hypnotics, Herbals »)", "mechanism": "Dépression additive potentielle du système nerveux central et somnolence accrue lors de l''association avec des sédatifs, hypnotiques ou barbituriques."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '0daccc19-6ba3-487e-a1a7-3c6234127a7f'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '0daccc19-6ba3-487e-a1a7-3c6234127a7f'::uuid AND lower(e.drug_name) = lower('Sedatives and CNS depressants'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '8811c8f3-f079-4692-9967-721d0212b5c4'::uuid, 'Corticosteroids (Prednisone)', '8640', 'moderate'::interaction_severity, 'There is little information of whether acute or chronic khat use is associated with serum enzyme elevations or alterations in liver function. However, in recent years several individual case reports and small case series of serious acute and chronic liver injury attributed to khat have been published, largely from the UK and Europe and in immigrants from areas of the world where khat use is frequent. The onset of injury usually occurs after years of khat use and can present acutely with nausea, fatigue, pruritus and jaundice or chronically, with signs and complications of portal hypertension. The pattern of liver enzyme elevations is typically hepatocellular and, in acute cases, the aminotransferase levels can be markedly elevated. Autoantibodies occur in a proportion of cases and the disease often resembles autoimmune hepatitis with chronic inflammation and fibrosis. However, responses to corticosteroid therapy are usually only partial, at least if khat use continued. Immunoallergic features (rash, fever, eosinophilia) are not common. Some patients suffer from multiple bouts of acute injury which leads to fibrosis and cirrhosis, portal hypertension and hepatic failure. Resolution occurs if khat chewing is stopped, but relapses are common, even in some patients who deny relapse in khat use. While most cases have been described from Europe and North America, chronic liver disease and cirrhosis of unknown cause are frequent in areas of the world where khat is commonly used. Consult a physician or pharmacist before combining with systemic corticosteroids.', 'Concomitant use with corticosteroids may increase the risk of potassium depletion or electrolyte imbalance, or alter immunological effects.', 'B', 'LiverTox', 'https://www.ncbi.nlm.nih.gov/books/n/livertox/Khat/', '{"fr": {"drug_name": "Corticostéroïdes (Prednisone)", "description": "Consultez un médecin ou un pharmacien avant toute association avec des corticostéroïdes systémiques. (Source officielle : LiverTox — « There is little information of whether acute or chronic khat use is associated with serum enzyme elevations or alterations in liver function. However, in recent years several individual case reports and small case series of serious acute and chronic liver injury attributed to khat have been published, largely from the UK and Europe and in immigrants from areas of the world where khat use is frequent. The onset of injury usually occurs after years of khat use and can present acutely with nausea, fatigue, pruritus and jaundice or chronically, with signs and complications of portal hypertension. The pattern of liver enzyme elevations is typically hepatocellular and, in acute cases, the aminotransferase levels can be markedly elevated. Autoantibodies occur in a proportion of cases and the disease often resembles autoimmune hepatitis with chronic inflammation and fibrosis. However, responses to corticosteroid therapy are usually only partial, at least if khat use continued. Immunoallergic features (rash, fever, eosinophilia) are not common. Some patients suffer from multiple bouts of acute injury which leads to fibrosis and cirrhosis, portal hypertension and hepatic failure. Resolution occurs if khat chewing is stopped, but relapses are common, even in some patients who deny relapse in khat use. While most cases have been described from Europe and North America, chronic liver disease and cirrhosis of unknown cause are frequent in areas of the world where khat is commonly used. »)", "mechanism": "L''utilisation concomitante avec des corticostéroïdes peut accroître le risque d''hypokaliémie, de déséquilibre électrolytique ou d''interaction immunologique."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '8811c8f3-f079-4692-9967-721d0212b5c4'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '8811c8f3-f079-4692-9967-721d0212b5c4'::uuid AND lower(e.drug_name) = lower('Corticosteroids (Prednisone)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '21c6070a-fd3a-45be-af93-a3548ba587b8'::uuid, 'Sedatives and CNS depressants', NULL, 'moderate'::interaction_severity, 'Interactions (4.5): with other medicinal products and other forms of interaction Well-established use Traditional use Patients taking MAO-inhibitor drugs should use Colae semen preparations with caution. Colae semen preparations like other caffeine containing preparations reduce action of sedative drugs and increase side effects caused by sympathomimetic drugs. Avoid combining with sedative or CNS-depressant medications without medical advice, and use caution when driving.', 'Potential additive central nervous system depression and drowsiness when combined with sedatives, hypnotics, or barbiturates.', 'B', 'European Medicines Agency (HMPC)', 'https://www.ema.europa.eu/en/documents/herbal-monograph/final-community-herbal-monograph-cola-nitida-vent-schott-et-endl-and-its-varieties-and-cola-acuminata-p-beauv-schott-et-endl-semen_en.pdf', '{"fr": {"drug_name": "Sédatifs et dépresseurs du SNC", "description": "Évitez l''association avec des sédatifs ou dépresseurs du SNC sans avis médical et soyez prudent lors de la conduite. (Source officielle : European Medicines Agency (HMPC) — « Interactions (4.5): with other medicinal products and other forms of interaction Well-established use Traditional use Patients taking MAO-inhibitor drugs should use Colae semen preparations with caution. Colae semen preparations like other caffeine containing preparations reduce action of sedative drugs and increase side effects caused by sympathomimetic drugs. »)", "mechanism": "Dépression additive potentielle du système nerveux central et somnolence accrue lors de l''association avec des sédatifs, hypnotiques ou barbituriques."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '21c6070a-fd3a-45be-af93-a3548ba587b8'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '21c6070a-fd3a-45be-af93-a3548ba587b8'::uuid AND lower(e.drug_name) = lower('Sedatives and CNS depressants'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '6b400e50-fc96-4843-9281-a71e4d6aba09'::uuid, 'Corticosteroids (Prednisone)', '8640', 'moderate'::interaction_severity, 'Chronic use of kratom recreationally has been associated with rare instances of acute liver injury. The onset of injury is usually within 1 to 8 weeks of starting regular use of kratom powder or tablets, with symptoms of fatigue, nausea, pruritus and dark urine followed by jaundice. The pattern of liver injury is typically cholestatic or mixed, and it can be severe with serum bilirubin levels rising above 20 mg/dL. The severe cholestasis can be accompanied by acute renal failure and bone marrow toxicity. Fever is common, but not rash or eosinophilia and autoantibodies are usually absent. The cholestasis can be prolonged, but usually resolves spontaneously. Corticosteroids as well as N-acetylcysteine have been used in cases of suspected kratom hepatotoxicity, but their efficacy is unproven. Kratom is a banned substance in many areas of the country and considered an agent of abuse rather than a dietary supplement. At least two dozen cases of clinically apparent liver injury with jaundice have been reported in the literature and a similar number reported to the Food and Drug Administration adverse event database. Consult a physician or pharmacist before combining with systemic corticosteroids.', 'Concomitant use with corticosteroids may increase the risk of potassium depletion or electrolyte imbalance, or alter immunological effects.', 'B', 'LiverTox', 'https://www.ncbi.nlm.nih.gov/books/n/livertox/Kratom/', '{"fr": {"drug_name": "Corticostéroïdes (Prednisone)", "description": "Consultez un médecin ou un pharmacien avant toute association avec des corticostéroïdes systémiques. (Source officielle : LiverTox — « Chronic use of kratom recreationally has been associated with rare instances of acute liver injury. The onset of injury is usually within 1 to 8 weeks of starting regular use of kratom powder or tablets, with symptoms of fatigue, nausea, pruritus and dark urine followed by jaundice. The pattern of liver injury is typically cholestatic or mixed, and it can be severe with serum bilirubin levels rising above 20 mg/dL. The severe cholestasis can be accompanied by acute renal failure and bone marrow toxicity. Fever is common, but not rash or eosinophilia and autoantibodies are usually absent. The cholestasis can be prolonged, but usually resolves spontaneously. Corticosteroids as well as N-acetylcysteine have been used in cases of suspected kratom hepatotoxicity, but their efficacy is unproven. Kratom is a banned substance in many areas of the country and considered an agent of abuse rather than a dietary supplement. At least two dozen cases of clinically apparent liver injury with jaundice have been reported in the literature and a similar number reported to the Food and Drug Administration adverse event database. »)", "mechanism": "L''utilisation concomitante avec des corticostéroïdes peut accroître le risque d''hypokaliémie, de déséquilibre électrolytique ou d''interaction immunologique."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '6b400e50-fc96-4843-9281-a71e4d6aba09'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '6b400e50-fc96-4843-9281-a71e4d6aba09'::uuid AND lower(e.drug_name) = lower('Corticosteroids (Prednisone)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT 'b55148eb-9db4-4818-9cf3-b465f212c9be'::uuid, 'Antihypertensives', NULL, 'moderate'::interaction_severity, 'Interactions (4.5): with other medicinal products and other forms of interaction Well-established use Traditional use Liquorice root may counteract antihypertensive action of prescribed medications. Not to be used concomitantly with diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance (see section with 4.4). Liquorice root preparations might affect the activity of CYP3A4. Clinical studies have shown that the oral intake of 300 mg/day of glycyrrhizin for 14 days can modestly decrease the systemic exposure to drugs metabolised by CYP 3A4 enzymes such as midazolam and omeprazole. Caution Consult a healthcare professional before use with blood pressure medications and monitor blood pressure regularly.', 'May alter blood pressure or interact additively/antagonistically with antihypertensive therapy according to regulatory monograph warnings.', 'B', 'European Medicines Agency (HMPC)', 'https://www.ema.europa.eu/en/documents/herbal-monograph/final-european-union-herbal-monograph-glycyrrhiza-glabra-l-glycyrrhiza-inflata-bat-glycyrrhiza-uralensis-fisch-radix-revision-1_en.pdf', '{"fr": {"drug_name": "Antihypertenseurs", "description": "Consultez un professionnel de la santé avant toute utilisation avec des médicaments contre l''hypertension et surveillez régulièrement la tension artérielle. (Source officielle : European Medicines Agency (HMPC) — « Interactions (4.5): with other medicinal products and other forms of interaction Well-established use Traditional use Liquorice root may counteract antihypertensive action of prescribed medications. Not to be used concomitantly with diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance (see section with 4.4). Liquorice root preparations might affect the activity of CYP3A4. Clinical studies have shown that the oral intake of 300 mg/day of glycyrrhizin for 14 days can modestly decrease the systemic exposure to drugs metabolised by CYP 3A4 enzymes such as midazolam and omeprazole. Caution »)", "mechanism": "Peut modifier la tension artérielle ou interagir avec un traitement antihypertenseur selon les avertissements de la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = 'b55148eb-9db4-4818-9cf3-b465f212c9be'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = 'b55148eb-9db4-4818-9cf3-b465f212c9be'::uuid AND lower(e.drug_name) = lower('Antihypertensives'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT 'b55148eb-9db4-4818-9cf3-b465f212c9be'::uuid, 'Digoxin', '3407', 'moderate'::interaction_severity, 'Interactions (4.5): with other medicinal products and other forms of interaction Well-established use Traditional use Liquorice root may counteract antihypertensive action of prescribed medications. Not to be used concomitantly with diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance (see section with 4.4). Liquorice root preparations might affect the activity of CYP3A4. Clinical studies have shown that the oral intake of 300 mg/day of glycyrrhizin for 14 days can modestly decrease the systemic exposure to drugs metabolised by CYP 3A4 enzymes such as midazolam and omeprazole. Caution Do not combine with digoxin or other cardiac glycosides without direct medical supervision.', 'Potential cardiac glycoside sensitivity shift (including via potassium depletion or P-glycoprotein/inotropic effects) noted in regulatory safety warnings.', 'B', 'European Medicines Agency (HMPC)', 'https://www.ema.europa.eu/en/documents/herbal-monograph/final-european-union-herbal-monograph-glycyrrhiza-glabra-l-glycyrrhiza-inflata-bat-glycyrrhiza-uralensis-fisch-radix-revision-1_en.pdf', '{"fr": {"drug_name": "Digoxine", "description": "Ne pas associer à la digoxine ou à d''autres glycosides cardiaques sans surveillance médicale directe. (Source officielle : European Medicines Agency (HMPC) — « Interactions (4.5): with other medicinal products and other forms of interaction Well-established use Traditional use Liquorice root may counteract antihypertensive action of prescribed medications. Not to be used concomitantly with diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance (see section with 4.4). Liquorice root preparations might affect the activity of CYP3A4. Clinical studies have shown that the oral intake of 300 mg/day of glycyrrhizin for 14 days can modestly decrease the systemic exposure to drugs metabolised by CYP 3A4 enzymes such as midazolam and omeprazole. Caution »)", "mechanism": "Modification potentielle de la sensibilité aux glycosides cardiaques (notamment par déplétion potassique ou effet inotrope/P-gp) signalée dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = 'b55148eb-9db4-4818-9cf3-b465f212c9be'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = 'b55148eb-9db4-4818-9cf3-b465f212c9be'::uuid AND lower(e.drug_name) = lower('Digoxin'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT 'b55148eb-9db4-4818-9cf3-b465f212c9be'::uuid, 'Corticosteroids (Prednisone)', '8640', 'moderate'::interaction_severity, 'Interactions (4.5): with other medicinal products and other forms of interaction Well-established use Traditional use Liquorice root may counteract antihypertensive action of prescribed medications. Not to be used concomitantly with diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance (see section with 4.4). Liquorice root preparations might affect the activity of CYP3A4. Clinical studies have shown that the oral intake of 300 mg/day of glycyrrhizin for 14 days can modestly decrease the systemic exposure to drugs metabolised by CYP 3A4 enzymes such as midazolam and omeprazole. Caution Consult a physician or pharmacist before combining with systemic corticosteroids.', 'Concomitant use with corticosteroids may increase the risk of potassium depletion or electrolyte imbalance, or alter immunological effects.', 'B', 'European Medicines Agency (HMPC)', 'https://www.ema.europa.eu/en/documents/herbal-monograph/final-european-union-herbal-monograph-glycyrrhiza-glabra-l-glycyrrhiza-inflata-bat-glycyrrhiza-uralensis-fisch-radix-revision-1_en.pdf', '{"fr": {"drug_name": "Corticostéroïdes (Prednisone)", "description": "Consultez un médecin ou un pharmacien avant toute association avec des corticostéroïdes systémiques. (Source officielle : European Medicines Agency (HMPC) — « Interactions (4.5): with other medicinal products and other forms of interaction Well-established use Traditional use Liquorice root may counteract antihypertensive action of prescribed medications. Not to be used concomitantly with diuretics, cardiac glycosides, corticosteroids, stimulant laxatives or other medications which may aggravate electrolyte imbalance (see section with 4.4). Liquorice root preparations might affect the activity of CYP3A4. Clinical studies have shown that the oral intake of 300 mg/day of glycyrrhizin for 14 days can modestly decrease the systemic exposure to drugs metabolised by CYP 3A4 enzymes such as midazolam and omeprazole. Caution »)", "mechanism": "L''utilisation concomitante avec des corticostéroïdes peut accroître le risque d''hypokaliémie, de déséquilibre électrolytique ou d''interaction immunologique."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = 'b55148eb-9db4-4818-9cf3-b465f212c9be'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = 'b55148eb-9db4-4818-9cf3-b465f212c9be'::uuid AND lower(e.drug_name) = lower('Corticosteroids (Prednisone)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '522a8ec4-2735-446d-8bfc-7446bd654815'::uuid, 'Corticosteroids (Prednisone)', '8640', 'moderate'::interaction_severity, 'Interactions between licorice and corticosteroids have been reported. Consult a physician or pharmacist before combining with systemic corticosteroids.', 'Concomitant use with corticosteroids may increase the risk of potassium depletion or electrolyte imbalance, or alter immunological effects.', 'B', 'NCCIH', 'https://www.nccih.nih.gov/health/licorice-root', '{"fr": {"drug_name": "Corticostéroïdes (Prednisone)", "description": "Consultez un médecin ou un pharmacien avant toute association avec des corticostéroïdes systémiques. (Source officielle : NCCIH — « Interactions between licorice and corticosteroids have been reported. »)", "mechanism": "L''utilisation concomitante avec des corticostéroïdes peut accroître le risque d''hypokaliémie, de déséquilibre électrolytique ou d''interaction immunologique."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '522a8ec4-2735-446d-8bfc-7446bd654815'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '522a8ec4-2735-446d-8bfc-7446bd654815'::uuid AND lower(e.drug_name) = lower('Corticosteroids (Prednisone)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '91e9e1ae-4eea-4c85-8db9-1a65cfab61a8'::uuid, 'Anticoagulants and Antiplatelets (Warfarin, Aspirin)', NULL, 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners (Gonzales and Gonzales-Castaneda 2009; Dording et al. 2008). Consult a healthcare professional and monitor coagulation parameters (such as INR or bleeding signs) when combining with anticoagulant or antiplatelet therapy.', 'Potential additive antiplatelet or anticoagulant activity, or altered anticoagulant metabolism noted in official regulatory safety guidance.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=maca.lepidium.meyenii2&lang=eng', '{"fr": {"drug_name": "Anticoagulants et antiplaquettaires (Warfarine, Aspirine)", "description": "Consultez un professionnel de la santé et surveillez les paramètres de coagulation (RIN ou signes de saignement) lors de l''association avec un traitement anticoagulant ou antiplaquettaire. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners (Gonzales and Gonzales-Castaneda 2009; Dording et al. 2008). »)", "mechanism": "Effet antiplaquettaire ou anticoagulant additif potentiel, ou altération du métabolisme des anticoagulants signalés dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '91e9e1ae-4eea-4c85-8db9-1a65cfab61a8'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '91e9e1ae-4eea-4c85-8db9-1a65cfab61a8'::uuid AND lower(e.drug_name) = lower('Anticoagulants and Antiplatelets (Warfarin, Aspirin)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '78ae29fc-d54f-4d31-8d32-9c52ede9de0b'::uuid, 'Anticoagulants and Antiplatelets (Warfarin, Aspirin)', NULL, 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners, birth control medication or hormone therapy (Brinker 2010; Barnes et al. 2007; Boon and Smith 2004). Consult a healthcare professional and monitor coagulation parameters (such as INR or bleeding signs) when combining with anticoagulant or antiplatelet therapy.', 'Potential additive antiplatelet or anticoagulant activity, or altered anticoagulant metabolism noted in official regulatory safety guidance.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=alfalfa2&lang=eng', '{"fr": {"drug_name": "Anticoagulants et antiplaquettaires (Warfarine, Aspirine)", "description": "Consultez un professionnel de la santé et surveillez les paramètres de coagulation (RIN ou signes de saignement) lors de l''association avec un traitement anticoagulant ou antiplaquettaire. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners, birth control medication or hormone therapy (Brinker 2010; Barnes et al. 2007; Boon and Smith 2004). »)", "mechanism": "Effet antiplaquettaire ou anticoagulant additif potentiel, ou altération du métabolisme des anticoagulants signalés dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '78ae29fc-d54f-4d31-8d32-9c52ede9de0b'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '78ae29fc-d54f-4d31-8d32-9c52ede9de0b'::uuid AND lower(e.drug_name) = lower('Anticoagulants and Antiplatelets (Warfarin, Aspirin)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '78ae29fc-d54f-4d31-8d32-9c52ede9de0b'::uuid, 'Oral Contraceptives', NULL, 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners, birth control medication or hormone therapy (Brinker 2010; Barnes et al. 2007; Boon and Smith 2004). Consult a healthcare practitioner before use if taking oral contraceptives or hormone-containing medications.', 'Potential hormonal or metabolic interaction with estrogen/progestin oral contraceptives noted in official regulatory monograph cautions.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=alfalfa2&lang=eng', '{"fr": {"drug_name": "Contraceptifs oraux", "description": "Consultez un professionnel de la santé avant utilisation si vous prenez des contraceptifs oraux ou des médicaments hormonaux. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners, birth control medication or hormone therapy (Brinker 2010; Barnes et al. 2007; Boon and Smith 2004). »)", "mechanism": "Interaction hormonale ou métabolique potentielle avec les contraceptifs oraux signalée dans les précautions de la monographie officielle."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '78ae29fc-d54f-4d31-8d32-9c52ede9de0b'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '78ae29fc-d54f-4d31-8d32-9c52ede9de0b'::uuid AND lower(e.drug_name) = lower('Oral Contraceptives'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '78ae29fc-d54f-4d31-8d32-9c52ede9de0b'::uuid, 'Hormone replacement therapy', NULL, 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners, birth control medication or hormone therapy (Brinker 2010; Barnes et al. 2007; Boon and Smith 2004). Consult a healthcare professional before combining with hormone replacement therapy.', 'Potential phytoestrogenic, dopaminergic, or endocrine receptor interaction with hormone replacement therapy noted in regulatory monograph warnings.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=alfalfa2&lang=eng', '{"fr": {"drug_name": "Hormonothérapie substitutive", "description": "Consultez un professionnel de la santé avant d''associer ce produit à une hormonothérapie substitutive. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners, birth control medication or hormone therapy (Brinker 2010; Barnes et al. 2007; Boon and Smith 2004). »)", "mechanism": "Interaction phytoœstrogénique, dopaminergique ou endocrinienne potentielle avec l''hormonothérapie substitutive signalée dans la monographie officielle."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '78ae29fc-d54f-4d31-8d32-9c52ede9de0b'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '78ae29fc-d54f-4d31-8d32-9c52ede9de0b'::uuid AND lower(e.drug_name) = lower('Hormone replacement therapy'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '8d431da2-7ecd-4318-9b59-65eef9455173'::uuid, 'Sedatives and CNS depressants', NULL, 'moderate'::interaction_severity, 'See also Drug Class: Sedatives and Hypnotics Avoid combining with sedative or CNS-depressant medications without medical advice, and use caution when driving.', 'Potential additive central nervous system depression and drowsiness when combined with sedatives, hypnotics, or barbiturates.', 'B', 'LiverTox', 'https://www.ncbi.nlm.nih.gov/books/n/livertox/Passionflower/', '{"fr": {"drug_name": "Sédatifs et dépresseurs du SNC", "description": "Évitez l''association avec des sédatifs ou dépresseurs du SNC sans avis médical et soyez prudent lors de la conduite. (Source officielle : LiverTox — « See also Drug Class: Sedatives and Hypnotics »)", "mechanism": "Dépression additive potentielle du système nerveux central et somnolence accrue lors de l''association avec des sédatifs, hypnotiques ou barbituriques."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '8d431da2-7ecd-4318-9b59-65eef9455173'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '8d431da2-7ecd-4318-9b59-65eef9455173'::uuid AND lower(e.drug_name) = lower('Sedatives and CNS depressants'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '07e192fa-7ea3-41f0-88ca-0c7c0ce73cff'::uuid, 'Digoxin', '3407', 'moderate'::interaction_severity, 'Interactions (4.5): with other medicinal products and other forms of interaction Well-established use Traditional use Enteral absorption of concomitantly administered medicines such as minerals, vitamins (B 12), cardiac glycosides, coumarin derivatives, carbamazepine and lithium may be delayed. For this reason the product should not be taken ½ to 1 hour before or after intake of other medicinal products. Diabetic patients should take ispaghula seeds only under medical supervision because adjustment of anti-diabetic therapy may be necessary. Use of ispaghula seed concomitantly with thyroid hormones requires medical supervision because the dose of the thyroid horm Do not combine with digoxin or other cardiac glycosides without direct medical supervision.', 'Potential cardiac glycoside sensitivity shift (including via potassium depletion or P-glycoprotein/inotropic effects) noted in regulatory safety warnings.', 'B', 'European Medicines Agency (HMPC)', 'https://www.ema.europa.eu/en/documents/herbal-monograph/final-community-herbal-monograph-plantago-ovata-forssk-semen_en.pdf', '{"fr": {"drug_name": "Digoxine", "description": "Ne pas associer à la digoxine ou à d''autres glycosides cardiaques sans surveillance médicale directe. (Source officielle : European Medicines Agency (HMPC) — « Interactions (4.5): with other medicinal products and other forms of interaction Well-established use Traditional use Enteral absorption of concomitantly administered medicines such as minerals, vitamins (B 12), cardiac glycosides, coumarin derivatives, carbamazepine and lithium may be delayed. For this reason the product should not be taken ½ to 1 hour before or after intake of other medicinal products. Diabetic patients should take ispaghula seeds only under medical supervision because adjustment of anti-diabetic therapy may be necessary. Use of ispaghula seed concomitantly with thyroid hormones requires medical supervision because the dose of the thyroid horm »)", "mechanism": "Modification potentielle de la sensibilité aux glycosides cardiaques (notamment par déplétion potassique ou effet inotrope/P-gp) signalée dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '07e192fa-7ea3-41f0-88ca-0c7c0ce73cff'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '07e192fa-7ea3-41f0-88ca-0c7c0ce73cff'::uuid AND lower(e.drug_name) = lower('Digoxin'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '07e192fa-7ea3-41f0-88ca-0c7c0ce73cff'::uuid, 'Levothyroxine (Synthroid)', '10582', 'moderate'::interaction_severity, 'Interactions (4.5): with other medicinal products and other forms of interaction Well-established use Traditional use Enteral absorption of concomitantly administered medicines such as minerals, vitamins (B 12), cardiac glycosides, coumarin derivatives, carbamazepine and lithium may be delayed. For this reason the product should not be taken ½ to 1 hour before or after intake of other medicinal products. Diabetic patients should take ispaghula seeds only under medical supervision because adjustment of anti-diabetic therapy may be necessary. Use of ispaghula seed concomitantly with thyroid hormones requires medical supervision because the dose of the thyroid horm Consult a physician before use with thyroid medications and monitor thyroid function tests if combined.', 'Potential interference with thyroid hormone replacement or thyroid function noted in regulatory safety guidance.', 'B', 'European Medicines Agency (HMPC)', 'https://www.ema.europa.eu/en/documents/herbal-monograph/final-community-herbal-monograph-plantago-ovata-forssk-semen_en.pdf', '{"fr": {"drug_name": "Lévothyroxine (Synthroid)", "description": "Consultez un médecin avant toute association avec des médicaments thyroïdiens et surveillez le bilan thyroïdien. (Source officielle : European Medicines Agency (HMPC) — « Interactions (4.5): with other medicinal products and other forms of interaction Well-established use Traditional use Enteral absorption of concomitantly administered medicines such as minerals, vitamins (B 12), cardiac glycosides, coumarin derivatives, carbamazepine and lithium may be delayed. For this reason the product should not be taken ½ to 1 hour before or after intake of other medicinal products. Diabetic patients should take ispaghula seeds only under medical supervision because adjustment of anti-diabetic therapy may be necessary. Use of ispaghula seed concomitantly with thyroid hormones requires medical supervision because the dose of the thyroid horm »)", "mechanism": "Interférence potentielle avec le traitement substitutif par hormone thyroïdienne ou la fonction thyroïdienne signalée dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '07e192fa-7ea3-41f0-88ca-0c7c0ce73cff'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '07e192fa-7ea3-41f0-88ca-0c7c0ce73cff'::uuid AND lower(e.drug_name) = lower('Levothyroxine (Synthroid)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '08fccb51-bcfc-49a0-92ac-3b0522406ab4'::uuid, 'Hormone replacement therapy', NULL, 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking any hormone replacement therapy (BfR 2007; HC 2006). Consult a healthcare professional before combining with hormone replacement therapy.', 'Potential phytoestrogenic, dopaminergic, or endocrine receptor interaction with hormone replacement therapy noted in regulatory monograph warnings.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=rcie&lang=eng', '{"fr": {"drug_name": "Hormonothérapie substitutive", "description": "Consultez un professionnel de la santé avant d''associer ce produit à une hormonothérapie substitutive. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking any hormone replacement therapy (BfR 2007; HC 2006). »)", "mechanism": "Interaction phytoœstrogénique, dopaminergique ou endocrinienne potentielle avec l''hormonothérapie substitutive signalée dans la monographie officielle."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '08fccb51-bcfc-49a0-92ac-3b0522406ab4'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '08fccb51-bcfc-49a0-92ac-3b0522406ab4'::uuid AND lower(e.drug_name) = lower('Hormone replacement therapy'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '7a085cb9-7082-4183-aba2-35dead387e78'::uuid, 'Corticosteroids (Prednisone)', '8640', 'moderate'::interaction_severity, 'In multiple small, short term placebo-controlled trials of Lingzhi or Reishi, serum aminotransferase levels did not change during treatment, and there were no reported instances of clinically apparent liver injury or jaundice. Furthermore, Lingzhi and Reishi are not listed in the many reviews of causes of liver injury from herbal and dietary supplements. Nevertheless, there have been a small number of reports from China, Japan, Thailand, and India of clinically apparent liver injury attributed to Lingzhi or Reishi or their extracts. The latency to onset was typically 1 to 2 months, but ranged from a few days to as long as 6 months, presenting with symptoms of fatigue, nausea, abdominal pain, poor appetite, dark urine, and jaundice. In published cases, the liver injury has been hepatocellular and immune allergic reactions (fever, rash) were not common. In some instances, low levels of autoantibodies were found but immunoglobulins were typically normal and liver biopsies were more suggestive of drug induced liver injury than autoimmune hepatitis. Severity in published cases ranged from mild and asymptomatic elevations in serum aminotransferase levels to clinically apparent hepatitis and even severe hepatitis with hepatic failure. Recovery was rapid once the herbal product was stopped and complete within 1 to 3 months with or without corticosteroid therapy. There have been no reports of chronicity. Many of the cases were poorly documented and the attribution to Ganoderma species somewhat weak. In some cases, other common causes of liver injury were not excluded (such as gallstones, acetaminophen overdose, exposure to other herbal products, contaminants of the herbal product). In view of the extensive worldwide use of Ganoderma lucidum and Lingzhi, clinically apparent liver injury from its use must be extremely rare. Consult a physician or pharmacist before combining with systemic corticosteroids.', 'Concomitant use with corticosteroids may increase the risk of potassium depletion or electrolyte imbalance, or alter immunological effects.', 'B', 'LiverTox', 'https://www.ncbi.nlm.nih.gov/books/n/livertox/Lingzhi/', '{"fr": {"drug_name": "Corticostéroïdes (Prednisone)", "description": "Consultez un médecin ou un pharmacien avant toute association avec des corticostéroïdes systémiques. (Source officielle : LiverTox — « In multiple small, short term placebo-controlled trials of Lingzhi or Reishi, serum aminotransferase levels did not change during treatment, and there were no reported instances of clinically apparent liver injury or jaundice. Furthermore, Lingzhi and Reishi are not listed in the many reviews of causes of liver injury from herbal and dietary supplements. Nevertheless, there have been a small number of reports from China, Japan, Thailand, and India of clinically apparent liver injury attributed to Lingzhi or Reishi or their extracts. The latency to onset was typically 1 to 2 months, but ranged from a few days to as long as 6 months, presenting with symptoms of fatigue, nausea, abdominal pain, poor appetite, dark urine, and jaundice. In published cases, the liver injury has been hepatocellular and immune allergic reactions (fever, rash) were not common. In some instances, low levels of autoantibodies were found but immunoglobulins were typically normal and liver biopsies were more suggestive of drug induced liver injury than autoimmune hepatitis. Severity in published cases ranged from mild and asymptomatic elevations in serum aminotransferase levels to clinically apparent hepatitis and even severe hepatitis with hepatic failure. Recovery was rapid once the herbal product was stopped and complete within 1 to 3 months with or without corticosteroid therapy. There have been no reports of chronicity. Many of the cases were poorly documented and the attribution to Ganoderma species somewhat weak. In some cases, other common causes of liver injury were not excluded (such as gallstones, acetaminophen overdose, exposure to other herbal products, contaminants of the herbal product). In view of the extensive worldwide use of Ganoderma lucidum and Lingzhi, clinically apparent liver injury from its use must be extremely rare. »)", "mechanism": "L''utilisation concomitante avec des corticostéroïdes peut accroître le risque d''hypokaliémie, de déséquilibre électrolytique ou d''interaction immunologique."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '7a085cb9-7082-4183-aba2-35dead387e78'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '7a085cb9-7082-4183-aba2-35dead387e78'::uuid AND lower(e.drug_name) = lower('Corticosteroids (Prednisone)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT 'fdab09bb-0d99-4279-bc1b-9e3eeebe41d7'::uuid, 'Digoxin', '3407', 'moderate'::interaction_severity, 'Interactions (4.5): with other medicinal products and other forms of interaction Traditional use Well-established use Hypokalaemia (resulting from long-term laxative abuse) potentiates the action of cardiac glycosides and interacts with antiarrhythmic medicinal products. Concomitant use with diuretics, adrenocorticosteroids and liquorice root may enhance loss of potassium. Do not combine with digoxin or other cardiac glycosides without direct medical supervision.', 'Potential cardiac glycoside sensitivity shift (including via potassium depletion or P-glycoprotein/inotropic effects) noted in regulatory safety warnings.', 'B', 'European Medicines Agency (HMPC)', 'https://www.ema.europa.eu/en/documents/herbal-monograph/european-union-herbal-monograph-rhamnus-frangula-l-cortex-revision-1_en.pdf', '{"fr": {"drug_name": "Digoxine", "description": "Ne pas associer à la digoxine ou à d''autres glycosides cardiaques sans surveillance médicale directe. (Source officielle : European Medicines Agency (HMPC) — « Interactions (4.5): with other medicinal products and other forms of interaction Traditional use Well-established use Hypokalaemia (resulting from long-term laxative abuse) potentiates the action of cardiac glycosides and interacts with antiarrhythmic medicinal products. Concomitant use with diuretics, adrenocorticosteroids and liquorice root may enhance loss of potassium. »)", "mechanism": "Modification potentielle de la sensibilité aux glycosides cardiaques (notamment par déplétion potassique ou effet inotrope/P-gp) signalée dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = 'fdab09bb-0d99-4279-bc1b-9e3eeebe41d7'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = 'fdab09bb-0d99-4279-bc1b-9e3eeebe41d7'::uuid AND lower(e.drug_name) = lower('Digoxin'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT 'b70e9b0f-c818-4645-b470-bc3d153691e1'::uuid, 'Oral Contraceptives', NULL, 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking antidepressant medication, hormone replacement therapy (HRT) or birth control medication (HC 2018; Iovieno et al. 2011; Olsson et al. 2009; Brown et al. 2002). Consult a healthcare practitioner before use if taking oral contraceptives or hormone-containing medications.', 'Potential hormonal or metabolic interaction with estrogen/progestin oral contraceptives noted in official regulatory monograph cautions.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=rhodiol2&lang=eng', '{"fr": {"drug_name": "Contraceptifs oraux", "description": "Consultez un professionnel de la santé avant utilisation si vous prenez des contraceptifs oraux ou des médicaments hormonaux. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking antidepressant medication, hormone replacement therapy (HRT) or birth control medication (HC 2018; Iovieno et al. 2011; Olsson et al. 2009; Brown et al. 2002). »)", "mechanism": "Interaction hormonale ou métabolique potentielle avec les contraceptifs oraux signalée dans les précautions de la monographie officielle."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = 'b70e9b0f-c818-4645-b470-bc3d153691e1'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = 'b70e9b0f-c818-4645-b470-bc3d153691e1'::uuid AND lower(e.drug_name) = lower('Oral Contraceptives'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT 'b70e9b0f-c818-4645-b470-bc3d153691e1'::uuid, 'Hormone replacement therapy', NULL, 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking antidepressant medication, hormone replacement therapy (HRT) or birth control medication (HC 2018; Iovieno et al. 2011; Olsson et al. 2009; Brown et al. 2002). Consult a healthcare professional before combining with hormone replacement therapy.', 'Potential phytoestrogenic, dopaminergic, or endocrine receptor interaction with hormone replacement therapy noted in regulatory monograph warnings.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=rhodiol2&lang=eng', '{"fr": {"drug_name": "Hormonothérapie substitutive", "description": "Consultez un professionnel de la santé avant d''associer ce produit à une hormonothérapie substitutive. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking antidepressant medication, hormone replacement therapy (HRT) or birth control medication (HC 2018; Iovieno et al. 2011; Olsson et al. 2009; Brown et al. 2002). »)", "mechanism": "Interaction phytoœstrogénique, dopaminergique ou endocrinienne potentielle avec l''hormonothérapie substitutive signalée dans la monographie officielle."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = 'b70e9b0f-c818-4645-b470-bc3d153691e1'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = 'b70e9b0f-c818-4645-b470-bc3d153691e1'::uuid AND lower(e.drug_name) = lower('Hormone replacement therapy'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '425c44a2-3673-4717-874b-8eeea2367aa9'::uuid, 'Hormone replacement therapy', NULL, 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking oral contraceptives or hormone replacement therapy (UpToDate 2024). Consult a healthcare professional before combining with hormone replacement therapy.', 'Potential phytoestrogenic, dopaminergic, or endocrine receptor interaction with hormone replacement therapy noted in regulatory monograph warnings.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=saw.palmetto.sabal2&lang=eng', '{"fr": {"drug_name": "Hormonothérapie substitutive", "description": "Consultez un professionnel de la santé avant d''associer ce produit à une hormonothérapie substitutive. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking oral contraceptives or hormone replacement therapy (UpToDate 2024). »)", "mechanism": "Interaction phytoœstrogénique, dopaminergique ou endocrinienne potentielle avec l''hormonothérapie substitutive signalée dans la monographie officielle."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '425c44a2-3673-4717-874b-8eeea2367aa9'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '425c44a2-3673-4717-874b-8eeea2367aa9'::uuid AND lower(e.drug_name) = lower('Hormone replacement therapy'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '5e394cca-4eb0-44cd-9acf-74112b001ff5'::uuid, 'Corticosteroids (Prednisone)', '8640', 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking heart medications, corticosteroids, diuretics, or other health products that may contribute to electrolyte imbalance (EMA 2018a,b; Brinker 2010; Blumenthal et al. 2000; WHO 1999). Consult a physician or pharmacist before combining with systemic corticosteroids.', 'Concomitant use with corticosteroids may increase the risk of potassium depletion or electrolyte imbalance, or alter immunological effects.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=senna.sene&lang=eng', '{"fr": {"drug_name": "Corticostéroïdes (Prednisone)", "description": "Consultez un médecin ou un pharmacien avant toute association avec des corticostéroïdes systémiques. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking heart medications, corticosteroids, diuretics, or other health products that may contribute to electrolyte imbalance (EMA 2018a,b; Brinker 2010; Blumenthal et al. 2000; WHO 1999). »)", "mechanism": "L''utilisation concomitante avec des corticostéroïdes peut accroître le risque d''hypokaliémie, de déséquilibre électrolytique ou d''interaction immunologique."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '5e394cca-4eb0-44cd-9acf-74112b001ff5'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '5e394cca-4eb0-44cd-9acf-74112b001ff5'::uuid AND lower(e.drug_name) = lower('Corticosteroids (Prednisone)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '794d9e6c-6eba-4af0-8376-5d7a6564f74d'::uuid, 'Anticoagulants and Antiplatelets (Warfarin, Aspirin)', NULL, 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners or anti-inflammatory medications (Bhagat et al. 2013; Chopra et al. 2009; Al-Khateeb and Nusair 2008; Mazzone et al. 1990). Consult a healthcare professional and monitor coagulation parameters (such as INR or bleeding signs) when combining with anticoagulant or antiplatelet therapy.', 'Potential additive antiplatelet or anticoagulant activity, or altered anticoagulant metabolism noted in official regulatory safety guidance.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=serrapeptase2&lang=eng', '{"fr": {"drug_name": "Anticoagulants et antiplaquettaires (Warfarine, Aspirine)", "description": "Consultez un professionnel de la santé et surveillez les paramètres de coagulation (RIN ou signes de saignement) lors de l''association avec un traitement anticoagulant ou antiplaquettaire. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners or anti-inflammatory medications (Bhagat et al. 2013; Chopra et al. 2009; Al-Khateeb and Nusair 2008; Mazzone et al. 1990). »)", "mechanism": "Effet antiplaquettaire ou anticoagulant additif potentiel, ou altération du métabolisme des anticoagulants signalés dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '794d9e6c-6eba-4af0-8376-5d7a6564f74d'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '794d9e6c-6eba-4af0-8376-5d7a6564f74d'::uuid AND lower(e.drug_name) = lower('Anticoagulants and Antiplatelets (Warfarin, Aspirin)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '29568fa8-f78d-4443-b2e6-0ebf0b9a6863'::uuid, 'Corticosteroids (Prednisone)', '8640', 'moderate'::interaction_severity, 'The severity of the liver injury in reports of spirulina hepatotoxicity has varied from mild, asymptomatic elevations in serum enzymes to self-limiting, clinically apparent hepatitis. There have been no reports of acute liver failure, chronic hepatitis or vanishing bile duct syndrome attributed to spirulina. There is no information on management or the role for corticosteroids or other interventions except for prompt discontinuation of the suspected agent. Consult a physician or pharmacist before combining with systemic corticosteroids.', 'Concomitant use with corticosteroids may increase the risk of potassium depletion or electrolyte imbalance, or alter immunological effects.', 'B', 'LiverTox', 'https://www.ncbi.nlm.nih.gov/books/n/livertox/Spirulina/', '{"fr": {"drug_name": "Corticostéroïdes (Prednisone)", "description": "Consultez un médecin ou un pharmacien avant toute association avec des corticostéroïdes systémiques. (Source officielle : LiverTox — « The severity of the liver injury in reports of spirulina hepatotoxicity has varied from mild, asymptomatic elevations in serum enzymes to self-limiting, clinically apparent hepatitis. There have been no reports of acute liver failure, chronic hepatitis or vanishing bile duct syndrome attributed to spirulina. There is no information on management or the role for corticosteroids or other interventions except for prompt discontinuation of the suspected agent. »)", "mechanism": "L''utilisation concomitante avec des corticostéroïdes peut accroître le risque d''hypokaliémie, de déséquilibre électrolytique ou d''interaction immunologique."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '29568fa8-f78d-4443-b2e6-0ebf0b9a6863'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '29568fa8-f78d-4443-b2e6-0ebf0b9a6863'::uuid AND lower(e.drug_name) = lower('Corticosteroids (Prednisone)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '6a8f278a-2f94-48f7-afd4-1cbfbc08ad92'::uuid, 'Anticoagulants and Antiplatelets (Warfarin, Aspirin)', NULL, 'moderate'::interaction_severity, '* Warfarin, an anticoagulant (blood thinner) Consult a healthcare professional and monitor coagulation parameters (such as INR or bleeding signs) when combining with anticoagulant or antiplatelet therapy.', 'Potential additive antiplatelet or anticoagulant activity, or altered anticoagulant metabolism noted in official regulatory safety guidance.', 'B', 'NCCIH', 'https://www.nccih.nih.gov/health/st-johns-wort', '{"fr": {"drug_name": "Anticoagulants et antiplaquettaires (Warfarine, Aspirine)", "description": "Consultez un professionnel de la santé et surveillez les paramètres de coagulation (RIN ou signes de saignement) lors de l''association avec un traitement anticoagulant ou antiplaquettaire. (Source officielle : NCCIH — « * Warfarin, an anticoagulant (blood thinner) »)", "mechanism": "Effet antiplaquettaire ou anticoagulant additif potentiel, ou altération du métabolisme des anticoagulants signalés dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '6a8f278a-2f94-48f7-afd4-1cbfbc08ad92'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '6a8f278a-2f94-48f7-afd4-1cbfbc08ad92'::uuid AND lower(e.drug_name) = lower('Anticoagulants and Antiplatelets (Warfarin, Aspirin)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '6a8f278a-2f94-48f7-afd4-1cbfbc08ad92'::uuid, 'Immunosuppressants', NULL, 'contraindicated'::interaction_severity, 'Do not use if you are taking antidepressants, anxiolytics, anti-cancer, cardiovascular, contraceptive medications, blood thinners, anti-HIV agents and/or medications to suppress the immune system (Brinker 2010; Barnes et al. 2007; Bradley 2006; Mills and Bone 2005; Murphy et al. 2005; Frye et al. 2004; Hebert et al. 2004; Jiang et al. 2004; Mueller et al. 2004; Smith et al. 2004; Sparreboom et al. 2004; Tannergren et al. 2004; Wichtl 2004; Alscher and Klotz 2003; Bauer et al. 2003; Dresser et al. 2003; ESCOP 2003; Hall et al. 2003; Hoffmann 2003; Pfrunder et al. 2003; Schwarz et al. 2003; Bolley 2002; Gorski et al. 2002; Mathijssen et al. 2002; Ahmed et al. 2001; De Maat et al. 2001; Moschella and Jaber 2001; Roby et al. 2001; Sugimoto et al. 2001; Turton-Weeks 2001; Wang et al. 2001; Barone et al. 2000; Durr et al. 2000; Karliova et al. 2000; Mai et al. 2000; Piscitelli et al. 2000; Ruschitzka et al. 2000; Ernst 1999; Johne et al. 1999; Maurer et al. 1999; Rey and Walter 1998). Consult a specialist before use if taking immunosuppressive therapy.', 'Immunostimulant or immunomodulatory botanicals may theoretically oppose the therapeutic action of immunosuppressive medications.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=stjohnswort.millepertuis.oral2&lang=eng', '{"fr": {"drug_name": "Immunosuppresseurs", "description": "Consultez un médecin spécialiste avant toute utilisation sous traitement immunosuppresseur. (Source officielle : Health Canada — « Do not use if you are taking antidepressants, anxiolytics, anti-cancer, cardiovascular, contraceptive medications, blood thinners, anti-HIV agents and/or medications to suppress the immune system (Brinker 2010; Barnes et al. 2007; Bradley 2006; Mills and Bone 2005; Murphy et al. 2005; Frye et al. 2004; Hebert et al. 2004; Jiang et al. 2004; Mueller et al. 2004; Smith et al. 2004; Sparreboom et al. 2004; Tannergren et al. 2004; Wichtl 2004; Alscher and Klotz 2003; Bauer et al. 2003; Dresser et al. 2003; ESCOP 2003; Hall et al. 2003; Hoffmann 2003; Pfrunder et al. 2003; Schwarz et al. 2003; Bolley 2002; Gorski et al. 2002; Mathijssen et al. 2002; Ahmed et al. 2001; De Maat et al. 2001; Moschella and Jaber 2001; Roby et al. 2001; Sugimoto et al. 2001; Turton-Weeks 2001; Wang et al. 2001; Barone et al. 2000; Durr et al. 2000; Karliova et al. 2000; Mai et al. 2000; Piscitelli et al. 2000; Ruschitzka et al. 2000; Ernst 1999; Johne et al. 1999; Maurer et al. 1999; Rey and Walter 1998). »)", "mechanism": "Les plantes immunostimulantes ou immunomodulatrices peuvent s''opposer à l''action thérapeutique des médicaments immunosuppresseurs."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '6a8f278a-2f94-48f7-afd4-1cbfbc08ad92'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '6a8f278a-2f94-48f7-afd4-1cbfbc08ad92'::uuid AND lower(e.drug_name) = lower('Immunosuppressants'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '6a8f278a-2f94-48f7-afd4-1cbfbc08ad92'::uuid, 'Saquinavir (Protease inhibitors)', '83395', 'moderate'::interaction_severity, 'Contraindications (4.3): Well-established use Traditional use Hypersensitivity to the active substance. Daily dose of hyperforin ≤ 1 mg: Concomitant use with coumarin-type Hypersensitivity to the active substance. anticoagulants, cyclosporine, everolimus, sirolimus, tacrolimus for systemic use, fosamprenavir, indinavir and other protease inhibitors, nucleoside reverse transcriptase inhibitors, irinotecan, imatinib and other cytostatic agents metabolised by CYP3A4, CYP2B6, CYP2C9, CYP2C19 or transported by P-glycoprotein (see section 4.5 ‘Interactions with other medicinal products and other forms of interaction’). Daily dose of hyperforin > 1 mg: Hypersensitivity to t Consult a healthcare provider before use if taking protease inhibitors or other antiretroviral medications.', 'Potential CYP3A4 or P-glycoprotein-mediated reduction in plasma concentrations of HIV protease inhibitors noted in regulatory guidance.', 'B', 'European Medicines Agency (HMPC)', 'https://www.ema.europa.eu/en/documents/herbal-monograph/final-european-union-herbal-monograph-hypericum-perforatum-l-herba-revision-1_en.pdf', '{"fr": {"drug_name": "Saquinavir (Inhibiteurs de la protéase)", "description": "Consultez un professionnel de la santé avant utilisation en cas de prise d''inhibiteurs de la protéase ou d''antirétroviraux. (Source officielle : European Medicines Agency (HMPC) — « Contraindications (4.3): Well-established use Traditional use Hypersensitivity to the active substance. Daily dose of hyperforin ≤ 1 mg: Concomitant use with coumarin-type Hypersensitivity to the active substance. anticoagulants, cyclosporine, everolimus, sirolimus, tacrolimus for systemic use, fosamprenavir, indinavir and other protease inhibitors, nucleoside reverse transcriptase inhibitors, irinotecan, imatinib and other cytostatic agents metabolised by CYP3A4, CYP2B6, CYP2C9, CYP2C19 or transported by P-glycoprotein (see section 4.5 ‘Interactions with other medicinal products and other forms of interaction’). Daily dose of hyperforin > 1 mg: Hypersensitivity to t »)", "mechanism": "Réduction potentielle des concentrations plasmatiques des inhibiteurs de la protéase via le CYP3A4 ou la P-glycoprotéine signalée dans la monographie officielle."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '6a8f278a-2f94-48f7-afd4-1cbfbc08ad92'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '6a8f278a-2f94-48f7-afd4-1cbfbc08ad92'::uuid AND lower(e.drug_name) = lower('Saquinavir (Protease inhibitors)'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '8819aca7-e7e2-44b7-916e-de72e1657984'::uuid, 'Sedatives and CNS depressants', NULL, 'moderate'::interaction_severity, 'Because it is possible (though not proven) that valerian might have a sleep-inducing effect, it should not be taken along with alcohol or sedatives. If you take any type of medicine, talk with your health care provider before using valerian or other herbal products; some herbs and medicines interact in harmful ways. Avoid combining with sedative or CNS-depressant medications without medical advice, and use caution when driving.', 'Potential additive central nervous system depression and drowsiness when combined with sedatives, hypnotics, or barbiturates.', 'B', 'NCCIH', 'https://www.nccih.nih.gov/health/valerian', '{"fr": {"drug_name": "Sédatifs et dépresseurs du SNC", "description": "Évitez l''association avec des sédatifs ou dépresseurs du SNC sans avis médical et soyez prudent lors de la conduite. (Source officielle : NCCIH — « Because it is possible (though not proven) that valerian might have a sleep-inducing effect, it should not be taken along with alcohol or sedatives. If you take any type of medicine, talk with your health care provider before using valerian or other herbal products; some herbs and medicines interact in harmful ways. »)", "mechanism": "Dépression additive potentielle du système nerveux central et somnolence accrue lors de l''association avec des sédatifs, hypnotiques ou barbituriques."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '8819aca7-e7e2-44b7-916e-de72e1657984'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '8819aca7-e7e2-44b7-916e-de72e1657984'::uuid AND lower(e.drug_name) = lower('Sedatives and CNS depressants'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '4bc028c8-9997-4794-98fb-1f1aff10fc64'::uuid, 'Hormone replacement therapy', NULL, 'moderate'::interaction_severity, 'In several short term clinical trials, chaste tree in conventional oral doses was typically described as having no or only mild adverse side effects, with no mention of either hepatotoxicity or ALT elevations. Furthermore, in multiple large series of drug and herbal product induced liver injury no cases of chaste tree associated injury have been reported. Single case reports of liver injury with jaundice attributed to chaste tree have been reported to manufacturers, but other possible diagnoses were not adequately excluded. Thus, there is little evidence that chaste tree in conventional oral doses causes clinically apparent liver injury with jaundice in humans. Because of its possible hormonal effects, use of high doses in persons with preexisting liver disease or cirrhosis is discouraged, and its use is not recommended in pregnant or breastfeeding women, or in women on birth control or hormone replacement. Consult a healthcare professional before combining with hormone replacement therapy.', 'Potential phytoestrogenic, dopaminergic, or endocrine receptor interaction with hormone replacement therapy noted in regulatory monograph warnings.', 'B', 'LiverTox', 'https://www.ncbi.nlm.nih.gov/books/n/livertox/ChasteTree/', '{"fr": {"drug_name": "Hormonothérapie substitutive", "description": "Consultez un professionnel de la santé avant d''associer ce produit à une hormonothérapie substitutive. (Source officielle : LiverTox — « In several short term clinical trials, chaste tree in conventional oral doses was typically described as having no or only mild adverse side effects, with no mention of either hepatotoxicity or ALT elevations. Furthermore, in multiple large series of drug and herbal product induced liver injury no cases of chaste tree associated injury have been reported. Single case reports of liver injury with jaundice attributed to chaste tree have been reported to manufacturers, but other possible diagnoses were not adequately excluded. Thus, there is little evidence that chaste tree in conventional oral doses causes clinically apparent liver injury with jaundice in humans. Because of its possible hormonal effects, use of high doses in persons with preexisting liver disease or cirrhosis is discouraged, and its use is not recommended in pregnant or breastfeeding women, or in women on birth control or hormone replacement. »)", "mechanism": "Interaction phytoœstrogénique, dopaminergique ou endocrinienne potentielle avec l''hormonothérapie substitutive signalée dans la monographie officielle."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '4bc028c8-9997-4794-98fb-1f1aff10fc64'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '4bc028c8-9997-4794-98fb-1f1aff10fc64'::uuid AND lower(e.drug_name) = lower('Hormone replacement therapy'));
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations) SELECT '45b9023a-2905-4235-ba9f-6bb71551f870'::uuid, 'Anticoagulants and Antiplatelets (Warfarin, Aspirin)', NULL, 'moderate'::interaction_severity, 'Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners or products containing salicylates (e.g., acetylsalicylic acid or non-steroidal anti-inflammatory drugs) (EMA 2017). Consult a healthcare professional and monitor coagulation parameters (such as INR or bleeding signs) when combining with anticoagulant or antiplatelet therapy.', 'Potential additive antiplatelet or anticoagulant activity, or altered anticoagulant metabolism noted in official regulatory safety guidance.', 'B', 'Health Canada', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=white.wil.saule.bla&lang=eng', '{"fr": {"drug_name": "Anticoagulants et antiplaquettaires (Warfarine, Aspirine)", "description": "Consultez un professionnel de la santé et surveillez les paramètres de coagulation (RIN ou signes de saignement) lors de l''association avec un traitement anticoagulant ou antiplaquettaire. (Source officielle : Health Canada — « Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners or products containing salicylates (e.g., acetylsalicylic acid or non-steroidal anti-inflammatory drugs) (EMA 2017). »)", "mechanism": "Effet antiplaquettaire ou anticoagulant additif potentiel, ou altération du métabolisme des anticoagulants signalés dans la monographie réglementaire."}}'::jsonb WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '45b9023a-2905-4235-ba9f-6bb71551f870'::uuid) AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = '45b9023a-2905-4235-ba9f-6bb71551f870'::uuid AND lower(e.drug_name) = lower('Anticoagulants and Antiplatelets (Warfarin, Aspirin)'));

-- ── 6. Polish French dosage_adult & dosage_child strings (0 residual English tokens) ──
UPDATE public.herbs SET translations = jsonb_set(translations, '{fr,dosage_adult}', to_jsonb('Dosage standard Kampo; généralement 2,5g de poudre 3× par jour'::text), true) WHERE slug = 'shakuyaku-kanzo-kampo' AND translations ? 'fr';
UPDATE public.herbs SET translations = jsonb_set(translations, '{fr,dosage_adult}', to_jsonb('Pâte ou jus de feuilles en application locale; infusion de feuilles : 1-2 tasses par jour pour un soutien interne'::text), true) WHERE slug = 'acapulco' AND translations ? 'fr';
UPDATE public.herbs SET translations = jsonb_set(translations, '{fr,dosage_adult}', to_jsonb('Herbe fraîche comme aliment; 2-4 g d''herbe séchée en infusion'::text), true) WHERE slug = 'anthriscus-cerefolium' AND translations ? 'fr';
UPDATE public.herbs SET translations = jsonb_set(translations, '{fr,dosage_adult}', to_jsonb('2–3 g racine sous forme de décoction; 2–3 mL teinture'::text), true) WHERE slug = 'wood-avens' AND translations ? 'fr';
UPDATE public.herbs SET translations = jsonb_set(translations, '{fr,dosage_adult}', to_jsonb('6–15g de rhizome séché en décoction; 500mg d''extrait 2 fois par jour'::text), true) WHERE slug = 'ze-xie' AND translations ? 'fr';
